//  LOGIN PAGE 
// Supports: Email/Password (sign-up + sign-in), Google (web popup or native
// Capacitor), and a Guest (name-only) fallback. Firebase SDK is loaded lazily
// from CDN so no npm install is needed for the web build; the Capacitor plugin
// (@capacitor-firebase/authentication) handles native Google Sign-In in the APK.
function LoginPage({ onLogin }) {
  // "login" | "signup" | "guest"
  const [mode, setMode]       = useState("login");
  const [email, setEmail]     = useState("");
  const [password, setPassword] = useState("");
  const [name, setName]       = useState("");    // used for signup + guest
  const [showPwd, setShowPwd] = useState(false);
  const [loading, setLoading] = useState(false);
  const [googleLoading, setGoogleLoading] = useState(false);
  const [error, setError]     = useState("");

  const resetFields = () => { setEmail(""); setPassword(""); setName(""); setError(""); };

  //  Email / Password 
  const handleEmailAuth = async () => {
    setError("");
    if (mode === "signup" && !name.trim()) { setError("Saisis ton prénom."); return; }
    if (!email.trim())    { setError("Adresse email requise."); return; }
    if (!password)        { setError("Mot de passe requis."); return; }
    setLoading(true);
    try {
      const { auth, authMod } = await loadFirebaseAuth();
      let cred;
      if (mode === "signup") {
        cred = await authMod.createUserWithEmailAndPassword(auth, email.trim(), password);
        if (name.trim()) {
          await authMod.updateProfile(cred.user, { displayName: name.trim() });
        }
      } else {
        cred = await authMod.signInWithEmailAndPassword(auth, email.trim(), password);
      }
      onLogin(firebaseUserToAppUser(cred.user, name.trim()));
    } catch (e) {
      setError(mapFirebaseError(e.code));
    } finally {
      setLoading(false);
    }
  };

  //  Google Sign-In 
  const handleGoogle = async () => {
    setError("");
    setGoogleLoading(true);
    try {
      if (isNativeApp()) {
        //  Capacitor APK — try native plugin first, fall back to redirect
        try {
          const appUser = await signInWithGoogleNative();
          onLogin(appUser);
          return;
        } catch (e1) {
          if (e1.message !== "PLUGIN_MISSING") throw e1;
          // Native plugin not installed — fall through to redirect
        }
      }
      //  Browser or APK fallback — use redirect (works in WebViews too)
      const { auth, authMod } = await loadFirebaseAuth();
      const provider = new authMod.GoogleAuthProvider();
      if (isWebView() && !isNativeApp()) {
        // WebView (not Capacitor): redirect is more reliable than popup
        sessionStorage.setItem("googleRedirectPending", "1");
        await authMod.signInWithRedirect(auth, provider);
        // Page will reload; result is picked up in App's useEffect
        return;
      }
      // Normal browser — popup works fine
      const cred = await authMod.signInWithPopup(auth, provider);
      onLogin(firebaseUserToAppUser(cred.user));
    } catch (e) {
      setError(mapGoogleSignInError(e));
      setGoogleLoading(false);
    }
  };

  //  Guest (name only, localStorage) 
  const handleGuest = () => {
    setError("");
    if (!name.trim()) { setError("Saisis ton prénom pour continuer."); return; }
    onLogin({
      uid: `guest-${Date.now()}`,
      name: name.trim(),
      email: "",
      avatar: null,
      provider: "guest",
    });
  };

  //  Shared input style 
  const inputStyle = {
    width:"100%", border:"1.5px solid #DDD6FE", borderRadius:10, padding:"13px 16px",
    fontSize:15, outline:"none", fontFamily:"'Segoe UI', system-ui, sans-serif",
    color:"#1E1B4B", background:"#FAFAFA", boxSizing:"border-box",
    transition:"border-color 0.2s, box-shadow 0.2s", letterSpacing:"0.01em",
  };

  return (
    <div style={{ fontFamily:"'Segoe UI', system-ui, sans-serif", minHeight:"100vh",
      background:"#F5EFE6", display:"flex", flexDirection:"column", alignItems:"center",
      justifyContent:"center", padding:"24px 16px" }}>
      <GlobalStyles />
      <style>{`
        @keyframes fadeSlide { from { opacity:0; transform:translateY(18px); } to { opacity:1; transform:translateY(0); } }
        @keyframes spin { to { transform: rotate(360deg); } }
        .lp-card { animation: fadeSlide 0.4s cubic-bezier(0.22,1,0.36,1) both; }
        .lp-input:focus { border-color:#7C3AED !important; box-shadow:0 0 0 3px rgba(124,58,237,0.12) !important; }
        .lp-tab { background:none; border:none; cursor:pointer; font-family:inherit;
                  padding:12px 0; font-size:13px; font-weight:600; letter-spacing:0.04em;
                  text-transform:uppercase; border-bottom:2px solid transparent;
                  transition:color 0.18s, border-color 0.18s; flex:1; }
        .lp-tab.active { border-bottom-color:#7C3AED; color:#7C3AED; }
        .lp-tab:not(.active) { color:#9CA3AF; }
        .lp-tab:not(.active):hover { color:#6D28D9; }
        .lp-google { display:flex; align-items:center; justify-content:center; gap:10px;
                     width:100%; background:#fff; border:1.5px solid #E5E7EB; border-radius:10px;
                     padding:13px; cursor:pointer; font-size:14px; font-weight:600;
                     color:#374151; font-family:inherit; letter-spacing:0.01em;
                     transition:border-color 0.18s, box-shadow 0.18s; }
        .lp-google:hover { border-color:#7C3AED; box-shadow:0 2px 12px rgba(124,58,237,0.10); }
        .lp-divider { display:flex; align-items:center; gap:12px; margin:18px 0; }
        .lp-divider::before, .lp-divider::after { content:''; flex:1; height:1px; background:#E9E6F0; }
        .lp-divider span { font-size:11px; color:#C4B5FD; font-weight:700; letter-spacing:0.08em; text-transform:uppercase; }
        .lp-spinner { width:17px; height:17px; border:2px solid rgba(255,255,255,0.35);
                      border-top-color:#fff; border-radius:50%; animation:spin 0.7s linear infinite; }
        .lp-spinner-dark { border-color:rgba(124,58,237,0.15); border-top-color:#7C3AED; }
        .lp-pwd-wrap { position:relative; }
        .lp-pwd-wrap input { padding-right:56px; }
        .lp-eye { position:absolute; right:12px; top:50%; transform:translateY(-50%);
                  background:none; border:none; cursor:pointer; padding:4px 6px;
                  font-size:11px; font-weight:700; color:#9CA3AF; font-family:inherit;
                  letter-spacing:0.04em; text-transform:uppercase; }
        .lp-eye:hover { color:#7C3AED; }
        .lp-link { background:none; border:none; color:#7C3AED; font-weight:600; cursor:pointer;
                   font-size:13px; font-family:inherit; padding:0; letter-spacing:0.01em;
                   text-decoration:underline; text-underline-offset:2px; }
        .lp-link:hover { color:#5B21B6; }
        .lp-forgot { background:none; border:none; color:#9CA3AF; font-size:12px; cursor:pointer;
                     font-family:inherit; padding:0; text-align:right; width:100%; margin-top:6px;
                     letter-spacing:0.01em; }
        .lp-forgot:hover { color:#7C3AED; }
        .lp-cta { width:100%; background:#7C3AED; color:#fff; border:none; border-radius:10px;
                  padding:14px; cursor:pointer; font-weight:700; font-size:15px;
                  font-family:inherit; letter-spacing:0.03em;
                  display:flex; align-items:center; justify-content:center; gap:10px;
                  transition:background 0.18s, box-shadow 0.18s; box-shadow:0 4px 16px rgba(124,58,237,0.28); }
        .lp-cta:hover { background:#6D28D9; box-shadow:0 6px 22px rgba(124,58,237,0.36); }
        .lp-cta:active { background:#5B21B6; }
        .lp-cta:disabled { background:#C4B5FD; box-shadow:none; cursor:default; }
        .lp-label { font-size:11px; font-weight:700; color:#6B7280; display:block;
                    margin-bottom:7px; letter-spacing:0.07em; text-transform:uppercase; }
      `}</style>

      {/*  Brand mark  */}
      <div style={{ marginBottom:28, textAlign:"center" }}>
        <div style={{ width:48, height:48, borderRadius:14, background:"#7C3AED",
          display:"flex", alignItems:"center", justifyContent:"center",
          margin:"0 auto 12px", boxShadow:"0 4px 16px rgba(124,58,237,0.30)" }}>
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
            <path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"
              stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
        </div>
        <div style={{ fontSize:20, fontWeight:800, color:"#1E1B4B", letterSpacing:"-0.3px" }}>SchoolMaroc</div>
        <div style={{ fontSize:12, color:"#9CA3AF", marginTop:3, letterSpacing:"0.03em" }}>
          La plateforme éducative marocaine
        </div>
      </div>

      {/*  Card  */}
      <div className="lp-card"
        style={{ width:"100%", maxWidth:420, background:"#fff",
          borderRadius:20, boxShadow:"0 4px 32px rgba(91,33,182,0.08), 0 1px 4px rgba(0,0,0,0.04)",
          overflow:"hidden", border:"1px solid #EDE9FE" }}>

        {/*  Tab bar  */}
        <div style={{ display:"flex", borderBottom:"1px solid #F3F0FB", background:"#FDFCFF" }}>
          <button className={`lp-tab${mode==="login"  ? " active" : ""}`}
            onClick={() => { setMode("login");  resetFields(); }}>Connexion</button>
          <button className={`lp-tab${mode==="signup" ? " active" : ""}`}
            onClick={() => { setMode("signup"); resetFields(); }}>Inscription</button>
          <button className={`lp-tab${mode==="guest"  ? " active" : ""}`}
            onClick={() => { setMode("guest");  resetFields(); }}>Invité</button>
        </div>

        <div style={{ padding:"28px 26px 32px" }}>

          {/*  Google button  */}
          {mode !== "guest" && (
            <>
              <button className="lp-google" onClick={handleGoogle} disabled={googleLoading}>
                {googleLoading
                  ? <div className="lp-spinner lp-spinner-dark" />
                  : <>
                      <svg width="18" height="18" viewBox="0 0 48 48">
                        <path fill="#4285F4" d="M47.5 24.5c0-1.6-.1-3.1-.4-4.5H24v8.5h13.2c-.6 3-2.3 5.5-4.9 7.2v6h7.9c4.6-4.2 7.3-10.5 7.3-17.2z"/>
                        <path fill="#34A853" d="M24 48c6.5 0 12-2.2 16-5.8l-7.9-6c-2.2 1.5-5 2.3-8.1 2.3-6.2 0-11.5-4.2-13.4-9.9H2.4v6.2C6.4 42.5 14.6 48 24 48z"/>
                        <path fill="#FBBC05" d="M10.6 28.6c-.5-1.5-.8-3-.8-4.6s.3-3.1.8-4.6v-6.2H2.4C.9 16.4 0 20.1 0 24s.9 7.6 2.4 10.8l8.2-6.2z"/>
                        <path fill="#EA4335" d="M24 9.5c3.5 0 6.6 1.2 9 3.6l6.8-6.8C35.9 2.2 30.4 0 24 0 14.6 0 6.4 5.5 2.4 13.2l8.2 6.2c1.9-5.7 7.2-9.9 13.4-9.9z"/>
                      </svg>
                      Continuer avec Google
                    </>
                }
              </button>
              <div className="lp-divider"><span>ou par email</span></div>
            </>
          )}

          {/*  Guest notice  */}
          {mode === "guest" && (
            <div style={{ background:"#F5F3FF", borderRadius:10, padding:"13px 16px",
              marginBottom:20, border:"1px solid #EDE9FE" }}>
              <div style={{ fontSize:11, color:"#6D28D9", fontWeight:700,
                letterSpacing:"0.06em", textTransform:"uppercase", marginBottom:4 }}>
                Mode sans compte
              </div>
              <div style={{ fontSize:13, color:"#6B7280", lineHeight:1.55 }}>
                Votre progression est sauvegardée uniquement sur cet appareil.
              </div>
            </div>
          )}

          {/*  Display name (signup + guest)  */}
          {(mode === "signup" || mode === "guest") && (
            <div style={{ marginBottom:16 }}>
              <label className="lp-label">{mode === "guest" ? "Votre prénom" : "Prénom"}</label>
              <input className="lp-input" style={inputStyle} value={name}
                onChange={e => { setName(e.target.value); setError(""); }}
                placeholder="ex : Yassine" autoFocus />
            </div>
          )}

          {/*  Email  */}
          {mode !== "guest" && (
            <div style={{ marginBottom:16 }}>
              <label className="lp-label">Adresse email</label>
              <input className="lp-input" style={inputStyle} type="email" value={email}
                onChange={e => { setEmail(e.target.value); setError(""); }}
                placeholder="vous@exemple.com"
                autoFocus={mode === "login"}
                onKeyDown={e => e.key === "Enter" && handleEmailAuth()} />
            </div>
          )}

          {/*  Password  */}
          {mode !== "guest" && (
            <div style={{ marginBottom: mode === "login" ? 4 : 18 }}>
              <label className="lp-label">
                Mot de passe
                {mode === "signup" && <span style={{ fontWeight:500, color:"#C4B5FD", marginLeft:6, textTransform:"none", letterSpacing:0 }}>6 car. min.</span>}
              </label>
              <div className="lp-pwd-wrap">
                <input className="lp-input" style={inputStyle} type={showPwd ? "text" : "password"}
                  value={password}
                  onChange={e => { setPassword(e.target.value); setError(""); }}
                  placeholder="••••••••"
                  onKeyDown={e => e.key === "Enter" && handleEmailAuth()} />
                <button className="lp-eye" onClick={() => setShowPwd(v => !v)}>
                  {showPwd ? "Cacher" : "Voir"}
                </button>
              </div>
            </div>
          )}

          {/*  Forgot password  */}
          {mode === "login" && (
            <button className="lp-forgot" onClick={async () => {
              setError("");
              if (!email.trim()) { setError("Saisissez votre email d'abord."); return; }
              try {
                const { auth, authMod } = await loadFirebaseAuth();
                await authMod.sendPasswordResetEmail(auth, email.trim());
                setError("OK Email de réinitialisation envoyé !");
              } catch (e) { setError(mapFirebaseError(e.code)); }
            }}>
              Mot de passe oublié ?
            </button>
          )}

          {/* Error / success */}
          {error && (
            <div style={{ marginTop:14, marginBottom:4,
              background: error.startsWith("OK") ? "#F0FDF4" : "#FEF2F2",
              borderRadius:9, padding:"10px 14px", fontSize:13,
              color: error.startsWith("OK") ? "#15803D" : "#B91C1C",
              fontWeight:600, border: error.startsWith("OK") ? "1px solid #BBF7D0" : "1px solid #FECACA" }}>
              {error}
            </div>
          )}

          {/*  Primary CTA  */}
          <div style={{ marginTop:22 }}>
            {mode === "guest" ? (
              <button className="lp-cta" onClick={handleGuest}>
                Accéder sans compte
              </button>
            ) : (
              <button className="lp-cta" onClick={handleEmailAuth} disabled={loading}>
                {loading
                  ? <><div className="lp-spinner" />{mode === "signup" ? "Création..." : "Connexion..."}</>
                  : mode === "signup" ? "Créer mon compte" : "Se connecter"
                }
              </button>
            )}
          </div>

          {/*  Switch mode  */}
          <div style={{ textAlign:"center", marginTop:20, fontSize:13, color:"#9CA3AF" }}>
            {mode === "guest" ? (
              <span style={{ fontSize:12, color:"#C4B5FD" }}>
                Aucune synchronisation — données locales uniquement
              </span>
            ) : mode === "login" ? (
              <>
                Pas encore de compte ?{" "}
                <button className="lp-link" onClick={() => { setMode("signup"); resetFields(); }}>
                  S'inscrire
                </button>
              </>
            ) : (
              <>
                Déjà un compte ?{" "}
                <button className="lp-link" onClick={() => { setMode("login"); resetFields(); }}>
                  Se connecter
                </button>
              </>
            )}
          </div>

        </div>
      </div>

      <div style={{ height:32 }} />
    </div>
  );
}


// Bottom nav bar (Matières / Quiz / Coachs / Profil)
let _setNavPage = null; // injected by App
const BottomNav = ({ active = "matieres" }) => {
  const tabs = [
    { id: "matieres", icon: null, imgSrc: "data:image/png;base64,", label: "Matières" },
    { id: "quiz",     icon: null, imgSrc: "data:image/png;base64,", label: "Mon quiz" },
    { id: "profil",   icon: null, imgSrc: "data:image/png;base64,", label: "Profil" },
  ];
  return (
    <div style={{ position: "fixed", bottom: 0, left: "50%", transform: "translateX(-50%)",
      width: "100%", maxWidth: "100%", background: "#fff",
      borderTop: "1px solid #E9D5FF", display: "flex", zIndex: 100,
      direction: "ltr",
      boxShadow: "0 -4px 20px rgba(124,58,237,0.08)" }}>
      {tabs.map(t => (
        <div key={t.id} className="tab-item"
          onClick={() => _setNavPage && _setNavPage(t.id)}
          style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center",
          padding: "8px 4px 12px", cursor: "pointer" }}>
          <div style={{
            width: 60, height: 56, borderRadius: 18,
            background: t.id === active ? "#EDE9FE" : "transparent",
            border: t.id === active ? "2.5px solid #C4B5FD" : "2.5px solid transparent",
            display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: 26, marginBottom: 4,
            transition: "background 0.2s, border 0.2s",
            boxShadow: t.id === active ? "0 2px 8px rgba(124,58,237,0.15)" : "none"
          }}>
            {t.imgSrc ? <img src={t.imgSrc} alt="Matières" style={{ width: 34, height: 34, objectFit: "contain" }} /> : t.icon}
          </div>
          <span style={{ fontSize: 11, fontWeight: t.id === active ? 900 : 500,
            color: t.id === active ? PURPLE : "#bbb",
            letterSpacing: t.id === active ? "0.01em" : "normal" }}>{t.label}</span>
        </div>
      ))}
    </div>
  );
};

//  PAGE: Mon Quiz 
function QuizPage({ onBack, onQuizDone, niveau, grade, filiere, matiere }) {
  const [topic, setTopic] = useState(null);
  const [questions, setQuestions] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [idx, setIdx] = useState(0);
  const [selected, setSelected] = useState(null);
  const [checked, setChecked] = useState(false);
  const [score, setScore] = useState(0);
  const [done, setDone] = useState(false);

  // Build topics dynamically from the user's chosen niveau/grade
  const ALL_SUBJECTS = [
    { id: "maths",      label: "الرياضيات",                        icon: "", color: "#9B59B6" },
    { id: "arabe",      label: "اللغة العربية",                    icon: "", color: "#E74C3C" },
    { id: "eveil",      label: "النشاط العلمي",                    icon: "", color: "#27AE60" },
    { id: "francais",   label: "Langue Française",                  icon: "", color: "#3498DB" },
    { id: "islam",      label: "التربية الإسلامية",                 icon: "", color: "#1ABC9C" },
    { id: "social",     label: "الاجتماعيات",                      icon: "", color: "#D35400" },
    { id: "sciences",   label: "Sciences de la Vie et de la Terre", icon: "", color: "#27AE60" },
    { id: "physique",   label: "Physique-Chimie",                   icon: "", color: "#2980B9" },
    { id: "histoire",   label: "التاريخ والجغرافيا",               icon: "", color: "#D35400" },
    { id: "anglais",    label: "English",                           icon: "", color: "#C0392B" },
    { id: "svt",        label: "SVT",                               icon: "", color: "#27AE60" },
    { id: "ses",        label: "Sciences Économiques",              icon: "", color: "#F39C12" },
    { id: "philo",      label: "الفلسفة",                          icon: "", color: "#8E44AD" },
    { id: "competences",label: "Compétences",                       icon: "", color: "#F39C12" },
    { id: "si",         label: "Sciences de l'Ingénieur",           icon: "", color: "#16A085" },
  ];

  // Determine which subjects belong to the chosen niveau/grade
  const getTopicsForContext = () => {
    if (!niveau || !grade) {
      const ids = ["maths","eveil","francais","arabe","islam"];
      return ids.map(id => ALL_SUBJECTS.find(s => s.id === id)).filter(Boolean);
    }
    const primaire6  = ["maths","eveil","francais","arabe","islam","social"];
    const primaire5  = ["maths","eveil","francais","arabe","islam","social"];
    const primaire4  = ["maths","eveil","francais","arabe","islam","social"];
    const primaire3  = ["maths","eveil","francais","competences","arabe","islam"];
    const primaire2  = ["maths","eveil","francais","arabe","islam"];
    const primaire1  = ["maths","eveil","francais","arabe","islam"];
    const college    = ["maths","physique","sciences","francais","anglais","arabe","social","islam"];
    const lycee      = ["maths","physique","svt","ses","francais","anglais","arabe","histoire","philo","islam"];
    const sciMaths   = ["maths","physique","si","svt","francais","anglais","arabe","histoire","philo"];

    let ids = [];
    if (niveau === "primaire") {
      if (grade.id === "6ap") ids = primaire6;
      else if (grade.id === "5ap") ids = primaire5;
      else if (grade.id === "4ap") ids = primaire4;
      else if (grade.id === "3ap") ids = primaire3;
      else if (grade.id === "2ap") ids = primaire2;
      else ids = primaire1;
    } else if (niveau === "college") {
      ids = college;
    } else if (niveau === "lycee") {
      ids = filiere?.id === "sci-maths" ? sciMaths : lycee;
    }
    return ids.map(id => ALL_SUBJECTS.find(s => s.id === id)).filter(Boolean);
  };

  const gradeLabel = grade ? grade.label : null;
  const niveauLabel = niveau && CURRICULUM_LABELS[niveau] ? CURRICULUM_LABELS[niveau] : null;

  const TOPICS = getTopicsForContext().map(s => ({
    ...s,
    quizLabel: gradeLabel ? `${s.label} — ${gradeLabel}` : s.label,
    isActive: matiere ? s.id === matiere.id : false,
  }));

  // Auto-start quiz when user arrives with a matiere already selected
  const autoStarted = useRef(false);
  useEffect(() => {
    if (matiere && !autoStarted.current) {
      autoStarted.current = true;
      const match = TOPICS.find(t => t.id === matiere.id);
      if (match) loadQuiz(match);
    }
  }, []);

  const loadQuiz = async (t) => {
    setTopic(t); setLoading(true); setError(null);
    setQuestions(null); setIdx(0); setSelected(null);
    setChecked(false); setScore(0); setDone(false);
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6", max_tokens: 1000,
          messages: [{ role: "user", content:
            `Generate exactly 5 multiple-choice questions for Moroccan school students on: "${t.quizLabel || t.label}".
Return ONLY a JSON array, no markdown, no preamble. Each item:
{"q":"question text","opts":["A","B","C","D"],"ans":"correct option text","exp":"brief explanation"}` }]
        })
      });
      const data = await res.json();
      const raw = (data.content||[]).map(b=>b.text||"").join("").replace(/```json|```/g,"").trim();
      setQuestions(JSON.parse(raw));
    } catch(e) { setError("حدث خطأ أثناء تحميل الأسئلة. حاول مجدداً."); }
    setLoading(false);
  };

  const next = () => {
    if (idx + 1 >= (questions||[]).length) {
      const pct = Math.round(((score + (checked && questions[idx] && selected === questions[idx].ans ? 1 : 0)) / questions.length) * 100);
      onQuizDone && onQuizDone(pct);
      setDone(true);
      return;
    }
    setIdx(i => i + 1); setSelected(null); setChecked(false);
  };

  //  Shared full-screen purple shell 
  const QuizShell = ({ color = PURPLE, children, showNav = true }) => (
    <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", minHeight: "100vh", width: "100%",
      background: `linear-gradient(170deg, ${color} 0%, ${PURPLE_DARK} 100%)`,
      position: "relative", overflow: "hidden" }}>
      <GlobalStyles />
      {/* blobs */}
      <div style={{ position:"absolute", top:-120, left:-120, width:340, height:340, borderRadius:"50%",
        background:"rgba(255,255,255,0.12)", pointerEvents:"none" }}/>
      <div style={{ position:"absolute", top:-60, right:-80, width:230, height:230, borderRadius:"50%",
        background:"rgba(255,255,255,0.08)", pointerEvents:"none" }}/>
      <div style={{ position:"absolute", top:280, left:-100, width:240, height:240, borderRadius:"50%",
        background:"rgba(255,255,255,0.08)", pointerEvents:"none" }}/>
      {/* bottom wave */}
      <svg style={{ position:"absolute", bottom:0, left:0, width:"100%", pointerEvents:"none", zIndex:0 }}
        viewBox="0 0 430 160" preserveAspectRatio="none">
        <path d="M0,130 Q30,80 70,110 Q110,140 150,90 Q180,50 210,80 Q240,110 280,60 Q310,20 350,55 Q385,85 430,50 L430,160 L0,160 Z"
          fill="rgba(0,0,0,0.20)"/>
        <path d="M-10,155 Q10,120 40,140 Q60,155 80,125 Q100,95 130,118 Q155,138 175,108 Q195,78 225,100 Q255,122 280,95 Q305,68 335,88 Q360,105 385,80 Q405,60 440,75 L440,160 L-10,160 Z"
          fill="rgba(0,0,0,0.28)"/>
      </svg>
      <div style={{ position:"relative", zIndex:1, minHeight:"100vh", display:"flex", flexDirection:"column",
        paddingBottom: showNav ? 120 : 0 }}>
        {children}
      </div>
      {showNav && <BottomNav active="quiz" />}
    </div>
  );

  if (!topic) return (
    <QuizShell>
      {/* Header */}
      <div style={{ padding:"24px 20px 20px" }}>
        <div style={{ fontSize:28, fontWeight:900, color:"#fff", marginBottom:4 }}> Mon Quiz</div>
        <div style={{ fontSize:14, color:"rgba(255,255,255,0.75)" }}>
          {niveauLabel && gradeLabel
            ? `${niveauLabel} • ${gradeLabel}${matiere ? ` • ${matiere.label}` : " — Choisir un sujet"}`
            : "Choisir un sujet pour commencer"}
        </div>
      </div>
      {/* Topic list — same card style as SubjectCard in Matières page */}
      <div style={{ padding:"0 18px 32px", display:"flex", flexDirection:"column", gap:14 }}>
        {TOPICS.map(t => (
          <button key={t.id} className="subject-card" onClick={() => loadQuiz(t)}
            style={{
              background: t.isActive ? t.color : "#fff",
              border: "none", borderRadius: 22,
              padding: 0, cursor: "pointer", textAlign: "left", overflow: "hidden",
              display: "flex", alignItems: "stretch", width: "100%", height: 100,
              boxShadow: "0 6px 0 rgba(80,0,140,0.35), 0 10px 20px rgba(0,0,0,0.12)",
              position: "relative",
              outline: t.isActive ? `3px solid ${t.color}` : "none",
              outlineOffset: 2,
            }}>
            <div style={{ flex: 1, display: "flex", flexDirection: "column",
              justifyContent: "center", padding: "0 22px", minWidth: 0 }}>
              <div style={{ fontSize: 17, fontWeight: 900, color: t.isActive ? "#fff" : DARK,
                lineHeight: 1.25, letterSpacing: -0.2 }}>{t.label}</div>
            </div>
            {t.id === "maths"    && <img src={MATH_IMG_SRC}     alt="" style={{ height: 100, width: "auto", display: "block" }} />}
            {t.id === "eveil"    && <img src={EVEIL_IMG_SRC}    alt="" style={{ height: 100, width: "auto", display: "block" }} />}
            {t.id === "social"   && <img src={SOCIAL_IMG_SRC}   alt="" style={{ height: 100, width: "auto", display: "block" }} />}
            {t.id === "islam"    && <img src={ISLAM_IMG_SRC}    alt="" style={{ height: 100, width: "auto", display: "block" }} />}
            {t.id === "francais" && <img src={FRANCAIS_IMG_SRC} alt="" style={{ height: 100, width: "auto", display: "block" }} />}
            {t.id === "arabe"    && <img src={ARABE_IMG_SRC}    alt="" style={{ height: 100, width: "auto", display: "block" }} />}
            {!["maths","eveil","social","islam","francais","arabe"].includes(t.id) && null}
          </button>
        ))}
      </div>
    </QuizShell>
  );

  if (loading) return (
    <QuizShell color={topic?.color || PURPLE} showNav={false}>
      <div style={{ padding:"20px 20px 0" }}>
        <div style={{ fontSize:24, fontWeight:900, color:"#fff", marginBottom:4 }}> Mon Quiz</div>
        <div style={{ fontSize:13, color:"rgba(255,255,255,0.75)" }}>تحميل الأسئلة…</div>
      </div>
      <div style={{ flex:1, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", gap:20 }}>
        <div style={{ fontSize:72 }}>⏳</div>
        <div style={{ fontSize:18, fontWeight:800, color:"#fff" }}>جاري تحميل الأسئلة…</div>
      </div>
    </QuizShell>
  );

  if (error) return (
    <QuizShell showNav={false}>
      <div style={{ padding:"20px 20px 0" }}>
        <div style={{ fontSize:24, fontWeight:900, color:"#fff", marginBottom:4 }}> Mon Quiz</div>
        <div style={{ fontSize:13, color:"rgba(255,255,255,0.75)" }}>حدث خطأ</div>
      </div>
      <div style={{ flex:1, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", gap:16, padding:"0 24px" }}>
        <div style={{ fontSize:64 }}></div>
        <div style={{ fontSize:15, color:"rgba(255,255,255,0.9)", textAlign:"center" }}>{error}</div>
        <button className="cta-btn" onClick={() => setTopic(null)}
          style={{ background:"#fff", color:PURPLE, border:"none", borderRadius:16, padding:"14px 32px",
            fontWeight:800, cursor:"pointer", fontSize:15,
            boxShadow:"0 6px 0 rgba(0,0,0,0.25)" }}>← رجوع</button>
      </div>
    </QuizShell>
  );

  if (done) {
    const pct = Math.round((score / questions.length) * 100);
    const emoji = pct >= 80 ? "" : pct >= 60 ? "" : "";
    const doneColor = pct >= 80 ? "#27AE60" : pct >= 60 ? "#F39C12" : PURPLE;
    return (
      <QuizShell color={doneColor} showNav={false}>
        <div style={{ flex:1, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center",
          gap:0, padding:"40px 24px 20px", textAlign:"center" }}>
          <div style={{ fontSize:72, marginBottom:8 }}>{emoji}</div>
          <div style={{ fontSize:48, fontWeight:900, color:"#fff", lineHeight:1 }}>{pct}%</div>
          <div style={{ fontSize:15, color:"rgba(255,255,255,0.8)", fontWeight:700, marginTop:8, marginBottom:32 }}>
            النتيجة: {score}/{questions.length}
          </div>
          <div style={{ background:"rgba(255,255,255,0.18)", borderRadius:18, padding:"16px 20px", marginBottom:32, width:"100%" }}>
            <div style={{ fontSize:15, fontWeight:700, color:"#fff" }}>
              {pct >= 80 ? "ممتاز! أحسنت الأداء. " : pct >= 60 ? "جيد! واصل المراجعة." : "لا بأس، راجع الدروس وحاول مجدداً."}
            </div>
          </div>
          <button className="cta-btn" onClick={() => loadQuiz(topic)}
            style={{ width:"100%", background:"#fff", color:doneColor, border:"none", borderRadius:18,
              padding:"18px", fontWeight:900, cursor:"pointer", fontSize:16, marginBottom:14,
              boxShadow:"0 6px 0 rgba(0,0,0,0.25)" }}> إعادة المحاولة</button>
          <button className="cta-btn" onClick={() => setTopic(null)}
            style={{ width:"100%", background:"rgba(255,255,255,0.20)", color:"#fff",
              border:"2px solid rgba(255,255,255,0.5)", borderRadius:18, padding:"16px",
              fontWeight:700, cursor:"pointer", fontSize:15 }}>← اختيار موضوع آخر</button>
        </div>
      </QuizShell>
    );
  }

  const q = questions[idx];
  const isRTL = topic.id !== "francais" || ["adab","sci-hum","arabe"].includes(filiere?.id);
  return (
    <QuizShell color={topic.color} showNav={false}>
      {/* Top bar */}
      <div style={{ position:"relative", zIndex:2, display:"flex", alignItems:"center",
        justifyContent:"space-between", padding:"20px 20px 0" }}>
        <button onClick={() => setTopic(null)} className="icon-btn"
          style={{ width:50, height:50, borderRadius:"50%", background:"rgba(60,0,100,0.40)",
            border:"none", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
            color:"#fff", fontSize:20, fontWeight:700 }}></button>
        {/* Progress counter */}
        <div style={{ background:"rgba(255,255,255,0.20)", borderRadius:20, padding:"8px 18px" }}>
          <span style={{ color:"#fff", fontSize:14, fontWeight:800 }}>{idx+1} / {questions.length}</span>
        </div>
      </div>

      {/* Progress bar */}
      <div style={{ padding:"16px 20px 0", direction:"ltr" }}>
        <div style={{ background:"rgba(255,255,255,0.25)", borderRadius:99, height:6 }}>
          <div style={{ height:"100%", borderRadius:99, background:"#fff",
            width:`${((idx+1)/questions.length)*100}%`, transition:"width 0.3s" }}/>
        </div>
      </div>

      {/* Subject circle */}
      <div style={{ display:"flex", flexDirection:"column", alignItems:"center", marginTop:24 }}>
        <div style={{ width:110, height:110, borderRadius:"50%", background:"#fff",
          display:"flex", alignItems:"center", justifyContent:"center",
          boxShadow:"0 8px 32px rgba(0,0,0,0.28)", position:"relative", zIndex:1 }}>
          <div style={{ width:50, height:50, borderRadius:"50%", background: topic.color, opacity:0.85 }} />
          <div style={{ position:"absolute", bottom:14, left:8, width:28, height:9,
            borderRadius:99, background:"#F5C518", transform:"rotate(-25deg)" }}/>
        </div>
        <div style={{ background:"rgba(30,10,60,0.50)", borderRadius:24, padding:"8px 26px",
          marginTop:-16, zIndex:2, boxShadow:"0 2px 12px rgba(0,0,0,0.25)" }}>
          <span style={{ color:"#fff", fontSize:14, fontWeight:800 }}>{topic.label}</span>
        </div>
      </div>

      {/* Question */}
      <div style={{ padding:"24px 28px 20px", textAlign:"center" }}>
        <div style={{ color:"#fff", fontSize:20, fontWeight:900, lineHeight:1.5, direction:isRTL?"rtl":"ltr" }}>
          {q.q}
        </div>
      </div>

      {/* Options */}
      <div style={{ padding:"0 18px", display:"flex", flexDirection:"column", gap:14, direction:isRTL?"rtl":"ltr" }}>
        {q.opts.map((opt, j) => {
          const isSel = selected === opt;
          const isOk  = checked && opt === q.ans;
          const isBad = checked && isSel && !isOk;
          return (
            <button key={j} className="option-btn" onClick={() => !checked && setSelected(opt)}
              style={{ background: isOk?"#E8F5E9": isBad?"#FFEBEE": "#fff",
                border: isSel && !checked ? "3px solid rgba(255,255,255,0.8)"
                  : isOk ? "3px solid #4CAF50"
                  : isBad ? "3px solid #F44336"
                  : "3px solid transparent",
                borderRadius:20, padding:"18px 22px", cursor:checked?"default":"pointer",
                textAlign:isRTL?"right":"left", fontSize:15, fontWeight:isSel?700:400,
                color: isOk?"#1B5E20": isBad?"#B71C1C": "#2a2a2a",
                boxShadow: isOk ? "0 6px 0 #388E3C, 0 10px 20px rgba(0,0,0,0.12)"
                  : isBad ? "0 6px 0 #D32F2F, 0 10px 20px rgba(0,0,0,0.12)"
                  : "0 6px 0 rgba(80,0,140,0.35), 0 10px 20px rgba(0,0,0,0.12)",
                display:"flex", alignItems:"center", justifyContent:"space-between",
                boxSizing:"border-box", transition:"all 0.15s ease" }}>
              <span>{opt}</span>
              {isOk  && <span style={{ fontSize:20 }}></span>}
              {isBad && <span style={{ fontSize:20 }}></span>}
            </button>
          );
        })}
      </div>

      {/* Explanation */}
      {checked && (
        <div style={{ margin:"16px 18px 0", background:"rgba(255,255,255,0.18)", borderRadius:16,
          padding:"14px 18px", direction:isRTL?"rtl":"ltr", textAlign:isRTL?"right":"left" }}>
          <div style={{ fontSize:13, fontWeight:800, color:"#FFD700", marginBottom:4 }}>
             {isRTL ? "التفسير" : "Explication"}
          </div>
          <div style={{ fontSize:14, color:"rgba(255,255,255,0.92)" }}>{q.exp}</div>
        </div>
      )}

      {/* CTA */}
      <div style={{ padding:"20px 18px 40px" }}>
        {!checked ? (
          <button className="cta-btn" onClick={() => { if (!selected) return; setChecked(true); if (selected === q.ans) setScore(s => s+1); }}
            style={{ width:"100%", background:selected?"#fff":"rgba(255,255,255,0.25)",
              border:"none", borderRadius:18, padding:"18px",
              cursor:selected?"pointer":"not-allowed", fontWeight:800, fontSize:17,
              color:selected?(topic.color||PURPLE):"rgba(255,255,255,0.5)",
              boxShadow:selected?"0 6px 0 rgba(0,0,0,0.25)":"none",
              transition:"all 0.2s" }}>
            {isRTL ? " تحقق من الإجابة" : " Vérifier"}
          </button>
        ) : (
          <button className="cta-btn" onClick={next}
            style={{ width:"100%", background:"#fff", border:"none", borderRadius:18, padding:"18px",
              cursor:"pointer", fontWeight:800, fontSize:17, color:topic.color||PURPLE,
              boxShadow:"0 6px 0 rgba(0,0,0,0.25)" }}>
            {idx+1 >= questions.length ? (isRTL?" النتيجة":" Résultat") : (isRTL?"التالي ›":"Suivant ›")}
          </button>
        )}
      </div>
    </QuizShell>
  );
}

//  PAGE: Coachs 
function CoachsPage() {
  const [coach, setCoach] = useState(null);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const bottomRef = useRef(null);

  const COACHES = [
    { id: "maths",    name: "Professeur Karim",   subject: "الرياضيات",        icon: "", color: "#9B59B6", persona: "You are Karim, a warm and encouraging Moroccan primary school math coach. Respond in simple Arabic (darija-friendly) with short, clear explanations. Use emojis occasionally." },
    { id: "arabe",    name: "الأستاذة سلمى",       subject: "اللغة العربية",    icon: "", color: "#E74C3C", persona: "You are Salma, a patient Arabic language coach for Moroccan primary school. Respond in Modern Standard Arabic, clearly explaining grammar and vocabulary." },
    { id: "eveil",    name: "Professeure Nadia",   subject: "النشاط العلمي",    icon: "", color: "#27AE60", persona: "You are Nadia, an enthusiastic science coach for Moroccan primary school. Respond in Arabic with fun science explanations. Use examples from daily Moroccan life." },
    { id: "francais", name: "Professeur Mehdi",    subject: "Langue Française", icon: "", color: "#3498DB", persona: "You are Mehdi, a friendly French language coach for Moroccan primary school students. Respond in simple French. Be encouraging and use simple vocabulary." },
    { id: "islam",    name: "الأستاذ يوسف",        subject: "التربية الإسلامية",icon: "", color: "#1ABC9C", persona: "You are Youssef, a knowledgeable and respectful Islamic education coach for Moroccan primary school. Respond in clear Modern Standard Arabic." },
    { id: "general",  name: "Coach Général",       subject: "Toutes matières",  icon: "", color: PURPLE,    persona: "You are a general study coach for Moroccan primary school students. Help with any subject, answer in the language the student uses (French or Arabic)." },
  ];

  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages]);

  const sendMessage = async () => {
    if (!input.trim() || loading) return;
    const userMsg = { role: "user", text: input.trim() };
    const newMsgs = [...messages, userMsg];
    setMessages(newMsgs); setInput(""); setLoading(true);
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6", max_tokens: 1000,
          system: coach.persona,
          messages: newMsgs.map(m => ({ role: m.role === "user" ? "user" : "assistant", content: m.text }))
        })
      });
      const data = await res.json();
      const reply = (data.content||[]).map(b=>b.text||"").join("").trim();
      setMessages(m => [...m, { role: "assistant", text: reply }]);
    } catch(e) { setMessages(m => [...m, { role: "assistant", text: "عذراً، حدث خطأ. حاول مجدداً." }]); }
    setLoading(false);
  };

  if (!coach) return (
    <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: HUB_BG, minHeight: "100vh", maxWidth: "100%", margin: "0 auto", paddingBottom: 120 }}>
      <GlobalStyles />
      <div style={{ background: `linear-gradient(160deg, ${PURPLE} 0%, ${PURPLE_DARK} 100%)`, height: "25vh", display: "flex", flexDirection: "column", justifyContent: "center", padding: "0 20px", position: "sticky", top: 0, zIndex: 0, overflow: "hidden", boxSizing: "border-box" }}>
        <HeroBg />
        <div style={{ position: "relative", zIndex: 1 }}>
          <div style={{ fontSize: 24, fontWeight: 800, color: "#fff", marginBottom: 4 }}> Coachs IA</div>
          <div style={{ fontSize: 13, color: "rgba(255,255,255,0.75)" }}>Choisis ton coach et pose tes questions</div>
        </div>
      </div>
      <div style={{ padding: "28px 16px 0", marginTop: -20, background: HUB_BG, borderTopLeftRadius: 20, borderTopRightRadius: 20, position: "relative", zIndex: 1 }}>
        <div style={{ fontSize: 12, fontWeight: 700, color: "#999", letterSpacing: 1, textTransform: "uppercase", marginBottom: 14 }}>Coachs disponibles</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
          {COACHES.map(c => (
            <button key={c.id} className="card-btn" onClick={() => { setCoach(c); setMessages([]); }}
              style={{ background: "#fff", border: "none", borderRadius: 20, padding: "20px 14px 16px", cursor: "pointer", textAlign: "center", boxShadow: "0 2px 16px rgba(124,58,237,0.08)", display: "flex", flexDirection: "column", alignItems: "center", gap: 0 }}>
              <div style={{ width: 64, height: 64, borderRadius: 18, background: c.color + "18", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 30, marginBottom: 10 }}>{c.icon}</div>
              <div style={{ fontSize: 13, fontWeight: 800, color: DARK, lineHeight: 1.3 }}>{c.name}</div>
              <div style={{ fontSize: 10, color: "#aaa", marginTop: 4 }}>{c.subject}</div>
            </button>
          ))}
        </div>
      </div>
      <BottomNav active="coachs" />
    </div>
  );

  const isRTL = coach.id !== "francais" && coach.id !== "general";
  return (
    <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: "#F3F4F6", minHeight: "100vh", maxWidth: "100%", margin: "0 auto", display: "flex", flexDirection: "column" }}>
      <GlobalStyles />
      {/* Header */}
      <div style={{ background: `linear-gradient(160deg, ${coach.color} 0%, ${PURPLE_DARK} 100%)`, padding: "14px 18px 18px", display: "flex", alignItems: "center", gap: 14, direction: "ltr", flexShrink: 0, position: "sticky", top: 0, zIndex: 10 }}>
        <button onClick={() => setCoach(null)} className="icon-btn"
          style={{ background: "rgba(255,255,255,0.2)", border: "none", borderRadius: 50, width: 38, height: 38, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}><img src={BACK_ICON_SRC} alt="back" style={{ width: 18, height: 18, filter: "brightness(0) invert(1)" }} /></button>
        <div style={{ width: 44, height: 44, borderRadius: 14, background: "rgba(255,255,255,0.2)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22 }}>{coach.icon}</div>
        <div>
          <div style={{ fontSize: 15, fontWeight: 800, color: "#fff" }}>{coach.name}</div>
          <div style={{ fontSize: 11, color: "rgba(255,255,255,0.75)" }}>{coach.subject}</div>
        </div>
      </div>
      {/* Messages */}
      <div style={{ flex: 1, overflowY: "auto", padding: "16px 14px", paddingBottom: 140, display: "flex", flexDirection: "column", gap: 10 }}>
        {messages.length === 0 && (
          <div style={{ textAlign: "center", padding: "40px 20px", color: "#aaa" }}>
            <div style={{ fontSize: 48, marginBottom: 12 }}>{coach.icon}</div>
            <div style={{ fontSize: 15, fontWeight: 700, color: DARK }}>{isRTL ? `مرحباً! أنا ${coach.name}` : `Bonjour! Je suis ${coach.name}`}</div>
            <div style={{ fontSize: 13, marginTop: 6 }}>{isRTL ? "اطرح سؤالك وسأساعدك." : "Pose-moi tes questions, je suis là pour t'aider!"}</div>
          </div>
        )}
        {messages.map((m, i) => (
          <div key={i} style={{ display: "flex", justifyContent: m.role === "user" ? "flex-end" : "flex-start" }}>
            <div style={{ maxWidth: "82%", background: m.role === "user" ? `linear-gradient(135deg, ${coach.color}, ${PURPLE_DARK})` : "#fff",
              color: m.role === "user" ? "#fff" : DARK, borderRadius: m.role === "user" ? "18px 18px 4px 18px" : "18px 18px 18px 4px",
              padding: "11px 15px", fontSize: 14, lineHeight: 1.6,
              boxShadow: "0 2px 10px rgba(0,0,0,0.08)",
              direction: isRTL ? "rtl" : "ltr", textAlign: isRTL ? "right" : "left" }}>
              {m.text}
            </div>
          </div>
        ))}
        {loading && (
          <div style={{ display: "flex", justifyContent: "flex-start" }}>
            <div style={{ background: "#fff", borderRadius: "18px 18px 18px 4px", padding: "12px 18px", boxShadow: "0 2px 10px rgba(0,0,0,0.08)", color: "#aaa", fontSize: 20, letterSpacing: 4 }}>• • •</div>
          </div>
        )}
        <div ref={bottomRef} />
      </div>
      {/* Input */}
      <div style={{ position: "fixed", bottom: 68, left: "50%", transform: "translateX(-50%)", width: "100%", maxWidth: "100%", background: "#fff", borderTop: "1px solid #E5E7EB", padding: "10px 14px", display: "flex", gap: 10, direction: "ltr", boxSizing: "border-box", zIndex: 50 }}>
        <input value={input} onChange={e => setInput(e.target.value)}
          onKeyDown={e => e.key === "Enter" && sendMessage()}
          placeholder={isRTL ? "اكتب سؤالك هنا…" : "Écris ta question ici…"}
          style={{ flex: 1, border: "2px solid #E5E7EB", borderRadius: 14, padding: "11px 14px", fontSize: 14, outline: "none", fontFamily: "inherit", direction: isRTL ? "rtl" : "ltr", color: DARK, background: "#F9FAFB" }} />
        <button onClick={sendMessage} disabled={!input.trim() || loading}
          style={{ background: input.trim() ? `linear-gradient(135deg,${coach.color},${PURPLE_DARK})` : "#E5E7EB", border: "none", borderRadius: 14, width: 46, height: 46, cursor: input.trim() ? "pointer" : "default", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20, flexShrink: 0 }}>
          {loading ? "⏳" : ""}
        </button>
      </div>
      <BottomNav active="coachs" />
    </div>
  );
}

//  PAGE: Profil 
function ProfilPage({ user, stats: s, onLogout, niveau, grade, filiere, matiere, setNiveau, setGrade, setFiliere, setMatiere, setPage, setNavPage }) {

  const niveauInfo  = niveau  ? CURRICULUM_LABELS[niveau] : null;
  const gradeInfo   = grade   ? grade.label : null;
  const filiereInfo = filiere ? filiere.label : null;
  const matiereInfo = matiere ? matiere.label : null;

  // Build subject label from the user's actual classe
  const subjectsByGrade = {
    "6ap": "Maths • Arabe • Français • Éveil • Islam • Social",
    "5ap": "Maths • Arabe • Français • Éveil • Islam • Social",
    "4ap": "Maths • Arabe • Français • Éveil • Islam • Social",
    "3ap": "Maths • Arabe • Français • Éveil • Islam • Compétences",
    "2ap": "Maths • Arabe • Français • Éveil • Islam",
    "1ap": "Maths • Arabe • Français • Éveil • Islam",
    "1ac": "Islam • Arabe • Aجتماعيات • Français • Maths • Physique • SVT • English",
    "2ac": "Islam • Arabe • Aجتماعيات • Français • Maths • Physique • SVT • English",
    "3ac": "Islam • Arabe • Aجتماعيات • Français • Maths • Physique • SVT • English",
    "tc":   "Maths • Arabe • Français • Physique • SVT • Anglais • Islam",
    "1bac": "Maths • Arabe • Français • Physique • SVT • SES • Philo • Anglais • Histoire • Islam",
    "2bac": "Maths • Arabe • Français • Physique • SVT • SES • Philo • Anglais • Histoire • Islam",
  };
  const matieresLabel = grade ? (subjectsByGrade[grade.id] || "Toutes matières") : "—";
  const niveauBadge   = niveauInfo && gradeInfo ? `${niveauInfo} • ${gradeInfo}` : (niveauInfo || "Non défini");

  const stats = [
    { label: "Quiz complétés", value: String(s.quizCompleted), icon: "", color: "#E74C3C" },
    { label: "Streak (jours)", value: String(s.streak),        icon: "", color: "#F39C12" },
  ];

  const badges = [
    { icon: "", label: "Bienvenue",        earned: true,                   color: "#9B59B6" },
    { icon: "", label: "Premier quiz",     earned: s.quizCompleted >= 1,   color: "#E74C3C" },
    { icon: "", label: "Première leçon",   earned: s.lessonsOpened >= 1,   color: "#27AE60" },
    { icon: "", label: "3 jours de suite", earned: s.streak >= 3,          color: "#F39C12" },
    { icon: "", label: "Score parfait",    earned: s.bestScore === 100,    color: "#3498DB" },
    { icon: "", label: "Tout explorer",    earned: s.quizCompleted >= 5 && s.lessonsOpened >= 5, color: "#1ABC9C" },
  ];
  return (
    <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: HUB_BG, minHeight: "100vh", maxWidth: "100%", margin: "0 auto", paddingBottom: 120 }}>
      <GlobalStyles />
      {/* Content */}
      <div style={{ padding: "28px 16px 0" }}>
        {/* Profile card */}
        <div style={{ background: `linear-gradient(160deg, ${PURPLE} 0%, ${PURPLE_DARK} 100%)`, borderRadius: 24, padding: "28px 20px", marginBottom: 20, display: "flex", flexDirection: "column", alignItems: "center", gap: 10, overflow: "hidden", position: "relative" }}>
          <HeroBg />
          <div style={{ position: "relative", zIndex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
            <div style={{ width: 72, height: 72, borderRadius: "50%", background: "rgba(255,255,255,0.2)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 36, fontWeight: 800, color: "#fff", border: "3px solid rgba(255,255,255,0.4)" }}>
              {(user?.name || "Y")[0].toUpperCase()}
            </div>
            <div style={{ fontSize: 22, fontWeight: 800, color: "#fff" }}>{user?.name?.split(" ")[0] || "Yassine"}</div>
          </div>
        </div>
        {/* Guest signup banner */}
        {user?.provider === "guest" && (
          <div onClick={onLogout} style={{ background: "#FFF7ED", border: "1.5px solid #FDBA74", borderRadius: 16, padding: "14px 16px", marginBottom: 20, display: "flex", alignItems: "center", gap: 12, cursor: "pointer" }}>
            
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 13, fontWeight: 800, color: "#9A3412" }}>Mode invité</div>
              <div style={{ fontSize: 12, color: "#C2410C", fontWeight: 500, lineHeight: 1.4 }}>Crée un compte pour sauvegarder ta progression et tes statistiques.</div>
            </div>
            <div style={{ fontSize: 18, color: "#C2410C", flexShrink: 0 }}>›</div>
          </div>
        )}
        {/* Stats grid */}
        <div style={{ fontSize: 12, fontWeight: 700, color: "#999", letterSpacing: 1, textTransform: "uppercase", marginBottom: 14 }}>Statistiques</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 28 }}>
          {stats.map((s, i) => (
            <div key={i} style={{ background: "#fff", borderRadius: 18, padding: "18px 14px", boxShadow: "0 2px 14px rgba(0,0,0,0.06)", display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
              <div style={{ fontSize: 26, fontWeight: 900, color: s.color }}>{s.value}</div>
              <div style={{ fontSize: 11, color: "#aaa", fontWeight: 600, textAlign: "center" }}>{s.label}</div>
            </div>
          ))}
        </div>
        {/* Badges */}
        <div style={{ fontSize: 12, fontWeight: 700, color: "#999", letterSpacing: 1, textTransform: "uppercase", marginBottom: 14 }}>Badges</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12, marginBottom: 28 }}>
          {badges.map((b, i) => (
            <div key={i} style={{ background: b.earned ? b.color + "18" : "#F9FAFB", borderRadius: 16, padding: "16px 10px", display: "flex", flexDirection: "column", alignItems: "center", gap: 6, opacity: b.earned ? 1 : 0.45, boxShadow: b.earned ? `0 2px 12px ${b.color}22` : "none" }}>
              <div style={{ width: 28, height: 28, borderRadius: "50%", background: b.earned ? b.color : "#ccc" }} />
              <div style={{ fontSize: 10, fontWeight: 700, color: b.earned ? b.color : "#aaa", textAlign: "center", lineHeight: 1.3 }}>{b.label}</div>
            </div>
          ))}
        </div>
        {/* Info card */}
        <div style={{ background: "#fff", borderRadius: 18, padding: "18px 20px", boxShadow: "0 2px 14px rgba(0,0,0,0.06)", marginBottom: 20 }}>
          <div style={{ fontSize: 13, fontWeight: 800, color: DARK, marginBottom: 14 }}>Informations</div>
          {[
            ["Niveau", niveauInfo || "—"],
            ["Classe", gradeInfo  || "—"],
            ...(filiereInfo ? [["Filière", filiereInfo]] : []),
            ["Matière active", matiereInfo ? `${matiereInfo}` : "—"],
            ["Matières", matieresLabel],
            ["Connexion", user?.provider === "google" ? "Google" : user?.provider === "guest" ? "Invité" : "Email"],
          ].map(([k, v]) => (
            <div key={k} style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", paddingBottom: 10, marginBottom: 10, borderBottom: "1px solid #F3F4F6", gap: 10 }}>
              <span style={{ fontSize: 12, color: "#aaa", fontWeight: 600, flexShrink: 0 }}>{k}</span>
              <span style={{ fontSize: 12, color: DARK, fontWeight: 700, textAlign: "right" }}>{v}</span>
            </div>
          ))}
        </div>
        {/* Change Niveau / Classe */}
        <button className="cta-btn"
          onClick={() => { setNavPage("matieres"); setPage(1); }}
          style={{ width: "100%", background: PURPLE, color: "#fff", border: "none", borderRadius: 16,
            padding: "16px", cursor: "pointer", fontWeight: 800, fontSize: 15, marginBottom: 20,
            boxShadow: "none",
            transition: "all 0.15s ease" }}>
          Modifier mon niveau et ma classe
        </button>

        {/* Logout */}
        <button onClick={onLogout} className="cta-btn"
          style={{ width: "100%", background: "#FEE2E2", color: "#DC2626", border: "none", borderRadius: 16,
            padding: "14px", cursor: "pointer", fontWeight: 800, fontSize: 14, marginBottom: 20,
            boxShadow: "none" }}>
          {user?.provider === "guest" ? "Quitter le mode invité" : "Se déconnecter"}
        </button>
      </div>
      <BottomNav active="profil" />
    </div>
  );
}

