function parseLesson(lesson) {
  const m = lesson.match(/^\[(.+?)\]\s*(.+)$/);
  if (m) return { tag: m[1], text: m[2] };
  return { tag: null, text: lesson };
}

// 
//  STATIC LESSON & EXERCISE CONTENT
// 
//
// HOW TO ADD A LESSON
// 
// 1. Find the right section below (grade → subject → unit → lesson title).
// 2. The key is the EXACT lesson title string from the DATA_* objects above.
// 3. Fill in the lesson object following this shape:
//
//    "الملايين والملايير": {
//      objective:    "one-sentence learning goal",
//      introduction: "2–3 sentence hook / context paragraph",
//      sections: [
//        { heading: "Section title", content: "Full paragraph of explanation" },
//        { heading: "Another section", content: "..." },
//      ],
//      keyPoints: ["Key point 1", "Key point 2", "Key point 3"],
//      example:  "A worked example or application",
//    },
//
// HOW TO ADD EXERCISES FOR A LESSON
// 
// Under the same key, add an `exercises` array.  Four types are supported:
//
//   qcm            → multiple-choice  (requires `options` array, `answer` = exact option text)
//   vrai_faux      → true/false       (answer = "صح" or "خطأ")
//   completion     → fill-in-blank    (answer = the missing word/phrase)
//   question_ouverte → open question  (answer = model answer for auto-correction)
//
//    exercises: {
//      lessonSummary: "Two-sentence recap shown above the exercises",
//      exercises: [
//        { type: "qcm",   question: "...", options: ["أ","ب","ج","د"], answer: "ب" },
//        { type: "vrai_faux",   question: "...", answer: "صح" },
//        { type: "completion",  question: "أكمل: الهواء يتكون من ______", answer: "النيتروجين والأكسجين" },
//        { type: "question_ouverte", question: "...", answer: "نموذج الجواب" },
//      ],
//    },
//
// STRUCTURE
// 
//  CONTENT["6ap"]["maths"]["الملايين والملايير"]  →  lesson + exercises
//  CONTENT["6ap"]["eveil"]["مكونات الهواء..."]    →  lesson + exercises
//  CONTENT["5ap"]["maths"]["..."]                 →  etc.
//  CONTENT["2ap"]["arabe"]["..."]                 →  etc.
//
// Grades: "6ap" | "5ap" | "4ap" | "3ap" | "2ap"
// Subjects: match the `id` field in MATIERES_* arrays
//   e.g. "maths" | "eveil" | "arabe" | "islam" | "social" | "francais"
