//  Lesson row with ripple 
function LessonRow({ lesson, i, tag, text, tagColor, onClick, isRTL }) {
  const { addRipple, RippleLayer } = useRipple();
  const rtl = !!isRTL;
  return (
    <button className="lesson-btn ripple-container"
      onClick={(e) => { addRipple(e); onClick(); }}
      style={{ background: "#fff", borderRadius: 13, padding: "12px 15px",
        display: "flex", flexDirection: rtl ? "row-reverse" : "row",
        alignItems: "flex-start", gap: 12, width: "100%",
        textAlign: rtl ? "right" : "left", direction: rtl ? "rtl" : "ltr",
        cursor: "pointer", border: "none", position: "relative",
        boxShadow: "0 2px 10px rgba(124,58,237,0.07)",
        borderRight: rtl ? `4px solid ${tagColor}` : "none",
        borderLeft: rtl ? "none" : `4px solid ${tagColor}` }}>
      <RippleLayer />
      <div style={{ width: 32, height: 32, borderRadius: 9, flexShrink: 0,
        background: i === 0 ? `linear-gradient(135deg, ${tagColor}, ${tagColor}BB)` : `${tagColor}18`,
        display: "flex", alignItems: "center", justifyContent: "center",
        fontSize: 13, fontWeight: 800, color: i === 0 ? "#fff" : tagColor }}>
        {i + 1}
      </div>
      <div style={{ flex: 1 }}>
        {tag && <div style={{ fontSize: 9, fontWeight: 800, color: tagColor,
          textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 3 }}>{tag}</div>}
        <div style={{ fontSize: 13, fontWeight: 600, color: DARK, lineHeight: 1.45 }}>{text}</div>
      </div>
      <div style={{ fontSize: 16, color: tagColor, marginTop: 2 }}></div>
    </button>
  );
}

//  APP 
export default function App() {
  const [user, setUser] = useState(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [stats, setStats] = useState(DEFAULT_STATS);
  const [statsLoaded, setStatsLoaded] = useState(false);

  // Load this user's stats whenever they sign in/out or switch accounts:
  // - real account → Firestore (users/{uid}), persists across logout/reinstall
  // - guest → localStorage on this device, persists across guest sessions
  // - signed out → reset to default (next login will load its own stats)
  useEffect(() => {
    let cancelled = false;
    setStatsLoaded(false);
    (async () => {
      if (!user) {
        setStats(DEFAULT_STATS);
        setStatsLoaded(true);
        return;
      }
      if (user.provider === "guest") {
        setStats(loadGuestStats());
        setStatsLoaded(true);
        return;
      }
      try {
        const loaded = await loadAccountStats(user.uid);
        if (!cancelled) setStats(loaded);
      } catch {
        if (!cancelled) setStats(DEFAULT_STATS);
      } finally {
        if (!cancelled) setStatsLoaded(true);
      }
    })();
    return () => { cancelled = true; };
  }, [user?.uid, user?.provider]);

  // Persist stats whenever they change (after the initial load has settled,
  // so we don't immediately overwrite freshly-loaded data with the defaults).
  useEffect(() => {
    if (!user || !statsLoaded) return;
    if (user.provider === "guest") {
      saveGuestStats(stats);
      return;
    }
    saveAccountStats(user.uid, stats).catch(() => {});
  }, [stats, user?.uid, user?.provider, statsLoaded]);

  //  Restore Firebase session on app launch 
  // onAuthStateChanged fires once immediately: with a User if already signed in,
  // or null if not. This lets the app skip the login page after a restart.
  // Guest sessions are stored in localStorage and are NOT tracked by Firebase.
  useEffect(() => {
    let unsubscribe = null;
    let cancelled = false;

    // Check for a persisted guest session first (so the spinner is skipped)
    const savedGuest = (() => {
      try { return JSON.parse(window.localStorage.getItem("school-maroc-guest-user") || "null"); } catch { return null; }
    })();
    if (savedGuest?.provider === "guest") {
      setUser(savedGuest);
      setAuthChecked(true);
      return;
    }

    loadFirebaseAuth().then(async ({ auth, authMod }) => {
      if (cancelled) return;

      //  Handle Google redirect result (WebView path) 
      // After signInWithRedirect, Firebase redirects back to the app.
      // getRedirectResult() resolves the credential on the landing page reload.
      if (sessionStorage.getItem("googleRedirectPending")) {
        sessionStorage.removeItem("googleRedirectPending");
        try {
          const result = await authMod.getRedirectResult(auth);
          if (result?.user && !cancelled) {
            setUser(firebaseUserToAppUser(result.user));
            setAuthChecked(true);
            return;
          }
        } catch (e) {
          // Redirect result failed — fall through to onAuthStateChanged
        }
      }

      unsubscribe = authMod.onAuthStateChanged(auth, (fbUser) => {
        if (cancelled) return;
        if (fbUser) {
          setUser(firebaseUserToAppUser(fbUser));
        } else {
          setUser(null);
        }
        setAuthChecked(true);
      });
    }).catch(() => {
      if (!cancelled) setAuthChecked(true); // Firebase failed to load — still show login
    });

    return () => {
      cancelled = true;
      if (unsubscribe) unsubscribe();
    };
  }, []);

  const handleLogout = async () => {
    try {
      if (user?.provider !== "guest") {
        const { auth, authMod } = await loadFirebaseAuth();
        await authMod.signOut(auth);
      } else {
        // Clear saved guest session
        try { window.localStorage.removeItem("school-maroc-guest-user"); } catch {}
      }
    } catch {}
    setUser(null);
  };

  const onQuizDone = (scorePct) => setStats(s => ({
    ...s, ...recordStreakAndDate(s),
    quizCompleted: s.quizCompleted + 1,
    bestScore: Math.max(s.bestScore || 0, scorePct)
  }));
  const onLessonOpened = () => setStats(s => ({
    ...s, ...recordStreakAndDate(s),
    lessonsOpened: s.lessonsOpened + 1
  }));

  const [navPage, setNavPage] = useState("matieres");
  const [page, setPage] = useState(() => savedNavLandsOnSubjects(loadSavedNav()) ? 3 : 1);
  const [niveau, setNiveau] = useState(() => loadSavedNav().niveau || null);
  const [grade, setGrade] = useState(() => loadSavedNav().grade || null);
  const [filiere, setFiliere] = useState(() => loadSavedNav().filiere || null);
  const [matiere, setMatiere] = useState(null);
  const [unitIdx, setUnitIdx] = useState(null);
  const [lessonIdx, setLessonIdx] = useState(null);
  const [exercises, setExercises] = useState(null);
  const [exercisesLoading, setExercisesLoading] = useState(false);
  const [exercisesError, setExercisesError] = useState(null);
  const [answers, setAnswers] = useState({});
  const [checked, setChecked] = useState(false);
  const [activeTab, setActiveTab] = useState("lecon");
  const [lessonContent, setLessonContent] = useState(null);
  const [lessonLoading, setLessonLoading] = useState(false);
  const [lessonError, setLessonError] = useState(null);

  // Scroll to top on every page change
  useEffect(() => { window.scrollTo({ top: 0, behavior: "instant" }); }, [page]);

  // Remember the last niveau/grade/filiere so reopening the app returns to
  // the subjects page instead of the niveau picker.
  useEffect(() => {
    try {
      window.localStorage.setItem(SAVED_NAV_KEY, JSON.stringify({
        niveauKey: niveau || null,
        gradeId: grade?.id || null,
        filiereId: filiere?.id || null,
      }));
    } catch {}
  }, [niveau, grade, filiere]);

  _setNavPage = (tab) => {
    setNavPage(tab);
    if (tab === "matieres") {
      if (niveau && grade && (["tc","1bac","2bac"].includes(grade.id) ? filiere : true)) setPage(3);
      else setPage(1);
    }
  };

  const headerFade = useScrollFade(100);
  const elastic = useElasticOverscroll();

  //  Login gate 
  // Persist guest user object so it survives app restarts
  useEffect(() => {
    if (user?.provider === "guest") {
      try { window.localStorage.setItem("school-maroc-guest-user", JSON.stringify(user)); } catch {}
    }
  }, [user]);

  if (!authChecked) {
    return (
      <div style={{ position:"fixed", inset:0, display: "flex", alignItems: "center", justifyContent: "center", background: HUB_BG }}>
        <div style={{ width: 36, height: 36, border: "4px solid #E5E7EB", borderTopColor: PURPLE, borderRadius: "50%", animation: "spin 0.8s linear infinite" }} />
        <style>{`
          @keyframes spin { to { transform: rotate(360deg); } }
          html, body { margin:0; padding:0; background: #F5EFE6; }
        `}</style>
      </div>
    );
  }
  if (!user) return <><GlobalStyles /><LoginPage onLogin={setUser} /></>;

  if (navPage === "quiz")   return <><GlobalStyles /><QuizPage onBack={() => setNavPage("matieres")} onQuizDone={onQuizDone} niveau={niveau} grade={grade} filiere={filiere} matiere={matiere} /></>;
  if (navPage === "profil") return <><GlobalStyles /><ProfilPage user={user} stats={stats} onLogout={handleLogout} niveau={niveau} grade={grade} filiere={filiere} matiere={matiere} setNiveau={setNiveau} setGrade={setGrade} setFiliere={setFiliere} setMatiere={setMatiere} setPage={setPage} setNavPage={setNavPage} /></>;

  const is6AP = niveau === "primaire" && grade?.id === "6ap";
  const is5AP = niveau === "primaire" && grade?.id === "5ap";
  const is4AP = niveau === "primaire" && grade?.id === "4ap";
  const is3AP = niveau === "primaire" && grade?.id === "3ap";
  const is2AP = niveau === "primaire" && grade?.id === "2ap";
  const is1AC = niveau === "college" && grade?.id === "1ac";
  const accentColor = niveau ? CURRICULUM[niveau].color : PURPLE;

  const getData = (id) => {
    if (is6AP) return DATA_6AP[id] || null;
    if (is5AP) return DATA_5AP[id] || null;
    if (is4AP) return DATA_4AP[id] || null;
    if (is3AP) return DATA_3AP[id] || null;
    if (is2AP) return DATA_2AP[id] || null;
    if (is1AC) return DATA_1AC[id] || null;
    return null;
  };

  const getMatieres = () => {
    if (is6AP) return MATIERES_6AP;
    if (is5AP) return MATIERES_5AP;
    if (is4AP) return MATIERES_4AP;
    if (is3AP) return MATIERES_3AP;
    if (is2AP) return MATIERES_2AP;
    if (is1AC) return MATIERES_1AC;
    if (niveau === "primaire") return MATIERES_PRIMAIRE;
    if (niveau === "college") return MATIERES_COLLEGE;
    if (niveau === "lycee") {
      if (filiere?.id === "sci-maths") return MATIERES_SCI_MATHS;
      return MATIERES_LYCEE;
    }
    return [];
  };

  // Arabic filières force RTL regardless of matiere
  const ARABIC_FILIERE_IDS = ["adab", "sci-hum", "arabe"];
  const isArabicFiliere = ARABIC_FILIERE_IDS.includes(filiere?.id);

  // Subjects whose lesson titles are in French/English → always LTR
  const LTR_SUBJECT_IDS = ["francais", "anglais", "maths", "physique", "sciences", "svt", "ses", "si", "competences"];
  const subjectIsRTL = (mid) => !LTR_SUBJECT_IDS.includes(mid) || isArabicFiliere;

  //  Shared mini header for inner pages (units / lessons / lesson detail) 
  const InnerHeader = ({ title, subtitle, onBack, color = PURPLE, isRTL = false, matiereId = null }) => {
    const fade = headerFade;

    // Resolve the grade-level "tier" for the current selection. Tiers:
    // primaire | college | lycee (filière générale) | sci-maths (Sciences Mathématiques)
    const isSciMathsFiliere = niveau === "lycee" && filiere?.id === "sci-maths";
    const tier = niveau === "primaire" ? "primaire"
      : niveau === "college" ? "college"
      : niveau === "lycee" ? (isSciMathsFiliere ? "sci-maths" : "lycee")
      : "primaire";

    // Per-subject variant registry: each subject lists which tiers it has a
    // custom design for, and falls back to its closest available tier's look
    // if the exact tier doesn't have its own design (e.g. histoire has no
    // primaire/collège variant since it doesn't exist at those levels, but if
    // ever reached, falls back to its lycée look rather than the plain default).
    const SUBJECT_HEADERS = {
      maths: {
        primaire: { grad: [MATH_BLUE_MID, MATH_BLUE_BASE], Bg: MathHeroBgPrimaire },
        college:  { grad: [MATH_TEAL_MID, MATH_TEAL_BASE], Bg: MathHeroBgCollege },
        lycee:    { grad: [MATH_INDIGO_MID, MATH_INDIGO_BASE], Bg: MathHeroBgLycee },
        "sci-maths": { grad: [MATH_NAVY_MID, MATH_NAVY_BASE], Bg: MathHeroBgSciMaths },
      },
      francais: {
        primaire: { grad: [FR_ROSE_MID, FR_ROSE_BASE], Bg: FrancaisHeroBgPrimaire },
        college:  { grad: [FR_PLUM_MID, FR_PLUM_BASE], Bg: FrancaisHeroBgCollege },
        lycee:    { grad: [FR_BURG_MID, FR_BURG_BASE], Bg: FrancaisHeroBgLycee },
        "sci-maths": { grad: [FR_BURG_MID, FR_BURG_BASE], Bg: FrancaisHeroBgSciMaths },
      },
      arabe: {
        primaire: { grad: [AR_EMERALD_MID, AR_EMERALD_BASE], Bg: ArabeHeroBgPrimaire },
        college:  { grad: [AR_JADE_MID, AR_JADE_BASE], Bg: ArabeHeroBgCollege },
        lycee:    { grad: [AR_DEEPGREEN_MID, AR_DEEPGREEN_BASE], Bg: ArabeHeroBgLycee },
        "sci-maths": { grad: [AR_DEEPGREEN_MID, AR_DEEPGREEN_BASE], Bg: ArabeHeroBgSciMaths },
      },
      islam: {
        primaire: { grad: [ISL_SOFTGREEN_MID, ISL_SOFTGREEN_BASE], Bg: IslamHeroBgPrimaire },
        college:  { grad: [ISL_TEAL_MID, ISL_TEAL_BASE], Bg: IslamHeroBgCollege },
        lycee:    { grad: [ISL_EMERALD_MID, ISL_EMERALD_BASE], Bg: IslamHeroBgLycee },
      },
      anglais: {
        college:  { grad: [EN_RED_MID, EN_RED_BASE], Bg: AnglaisHeroBgCollege },
        lycee:    { grad: [EN_DEEPRED_MID, EN_DEEPRED_BASE], Bg: AnglaisHeroBgLycee },
        "sci-maths": { grad: [EN_FORMALNAVY_MID, EN_FORMALNAVY_BASE], Bg: AnglaisHeroBgSciMaths },
      },
      physique: {
        college:  { grad: [PHY_ORANGE_MID, PHY_ORANGE_BASE], Bg: PhysiqueHeroBgCollege },
        lycee:    { grad: [PHY_DEEPORANGE_MID, PHY_DEEPORANGE_BASE], Bg: PhysiqueHeroBgLycee },
        "sci-maths": { grad: [PHY_AMBER_MID, PHY_AMBER_BASE], Bg: PhysiqueHeroBgSciMaths },
      },
      histoire: {
        lycee:    { grad: [HIST_SEPIA_MID, HIST_SEPIA_BASE], Bg: HistoireHeroBgLycee },
        "sci-maths": { grad: [HIST_SEPIA2_MID, HIST_SEPIA2_BASE], Bg: HistoireHeroBgSciMaths },
      },
      philo: {
        lycee:    { grad: [PHILO_PURPLE_MID, PHILO_PURPLE_BASE], Bg: PhiloHeroBgLycee },
        "sci-maths": { grad: [PHILO_MIDNIGHT_MID, PHILO_MIDNIGHT_BASE], Bg: PhiloHeroBgSciMaths },
      },
      svt: {
        lycee:    { grad: [SVT_FOREST_MID, SVT_FOREST_BASE], Bg: SvtHeroBgLycee },
        "sci-maths": { grad: [SVT_DEEPFOREST_MID, SVT_DEEPFOREST_BASE], Bg: SvtHeroBgSciMaths },
      },
      eveil:    { primaire: { grad: [EVEIL_GREEN_MID, EVEIL_GREEN_BASE], Bg: EveilHeroBg } },
      sciences: { college:  { grad: [SCI_TEAL_MID, SCI_TEAL_BASE], Bg: SciencesHeroBg } },
      ses:      { lycee:    { grad: [SES_BLUE_MID, SES_BLUE_BASE], Bg: SesHeroBg } },
      si:       { "sci-maths": { grad: [SI_STEEL_MID, SI_STEEL_BASE], Bg: SiHeroBg } },
    };

    // social/géo (primaire+collège) keeps its existing single design; histoire
    // (lycée+sci-maths) now gets its own distinct variants defined above.
    const usesSocialBg = matiereId === "social";
    const subjectEntry = SUBJECT_HEADERS[matiereId];
    const tierEntry = subjectEntry ? (subjectEntry[tier] || subjectEntry.lycee || subjectEntry.college || subjectEntry.primaire || subjectEntry["sci-maths"]) : null;

    const bgGradient = usesSocialBg
      ? `linear-gradient(160deg, ${SOCIAL_ORANGE_LIGHT} 0%, ${SOCIAL_ORANGE} 100%)`
      : tierEntry
      ? `linear-gradient(160deg, ${tierEntry.grad[0]} 0%, ${tierEntry.grad[1]} 100%)`
      : `linear-gradient(160deg, ${color} 0%, ${PURPLE_DARK} 100%)`;
    const SubjectBg = tierEntry ? tierEntry.Bg : null;

    return (
    <div style={{ background: bgGradient,
      padding: "0 20px", height: "25vh", display: "flex", flexDirection: "column", justifyContent: "center", position: "sticky", top: 0, zIndex: 0, overflow: "hidden", boxSizing: "border-box" }}>
      {usesSocialBg ? <SocialHeroBg /> : SubjectBg ? <SubjectBg /> : <HeroBg />}
      <div style={{ position: "absolute", inset: 0, background: HUB_BG, opacity: fade, pointerEvents: "none", transition: "opacity 0.05s linear" }} />
      {onBack && (
        <button onClick={onBack} className="icon-btn" style={{ position: "absolute", top: 14, left: 16, zIndex: 2,
          background: "#fff", border: "none",
          borderRadius: 50, width: 40, height: 40, cursor: "pointer",
          display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20, color: DARK, boxShadow: "0 2px 10px rgba(0,0,0,0.12)" }}><img src={BACK_ICON_SRC} alt="back" style={{ width: 18, height: 18 }} /></button>
      )}
      <div style={{ position: "relative", zIndex: 1, textAlign: "center", opacity: 1 - fade, transition: "opacity 0.05s linear" }}>
        <div style={{ color: "#fff", fontSize: 20, fontWeight: 800, lineHeight: 1.2, textAlign: "center" }}>{title}</div>
      </div>
    </div>
  );
  };

  const Crumb = ({ label, color, onClick }) => (
    <span onClick={onClick} className={onClick ? "crumb-btn" : undefined}
      style={{ fontSize: 11, background: color + "20", color,
      borderRadius: 20, padding: "3px 10px", cursor: onClick ? "pointer" : "default", fontWeight: 700 }}>
      {label}
    </span>
  );

  const Breadcrumbs = () => (
    <div style={{ display: "flex", gap: 6, padding: "8px 18px", flexWrap: "wrap" }}>
      {niveau && <Crumb label={`${CURRICULUM[niveau].label}`} color={PURPLE}
        onClick={() => { setNiveau(null); setGrade(null); setFiliere(null); setMatiere(null); setUnitIdx(null); setPage(1); }} />}
      {grade && <Crumb label={grade.label} color={PURPLE_DARK}
        onClick={() => { setGrade(null); setFiliere(null); setMatiere(null); setUnitIdx(null); setPage(1); }} />}
      {["tc","1bac","2bac"].includes(grade?.id) && filiere && <Crumb label={`${filiere.label}`} color={CURRICULUM[niveau].color}
        onClick={() => { setFiliere(null); setMatiere(null); setUnitIdx(null); setPage(1); }} />}
      {matiere && <Crumb label={matiere.label} color={matiere.color}
        onClick={() => { setUnitIdx(null); setPage(4); }} />}
      {unitIdx !== null && matiere && (is6AP || is5AP || is4AP || is3AP || is2AP || is1AC) && getData(matiere.id) && (() => {
        const unitData = getData(matiere.id);
        const unitTitle = unitData?.units?.[unitIdx]?.title;
        const fallback = !["francais","competences"].includes(matiere?.id) ? `الوحدة ${unitIdx + 1}` : `Unité ${unitIdx + 1}`;
        return <Crumb label={unitTitle || fallback} color="#92400E" onClick={null} />;
      })()}
    </div>
  );

  //  PAGE 1: Home / Niveau 
  if (page === 1 || page === 2) return (
    <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: HUB_BG,
      minHeight: "100vh", maxWidth: "100%", margin: "0 auto", paddingBottom: 120 }}>
      <GlobalStyles />

      {/*  Purple hero header  */}
      <div style={{ background: `linear-gradient(160deg, ${PURPLE} 0%, ${PURPLE_DARK} 100%)`,
        padding: "0 20px", height: "25vh", display: "flex", flexDirection: "column", justifyContent: "center", position: "sticky", top: 0, zIndex: 0, overflow: "hidden",
        borderBottomLeftRadius: 0, borderBottomRightRadius: 0, boxSizing: "border-box" }}>
        <HeroBg />
        <div style={{ position: "absolute", inset: 0, background: HUB_BG, opacity: headerFade, pointerEvents: "none", transition: "opacity 0.05s linear" }} />
        {/* Streak pill */}
        <div style={{ position: "absolute", top: 14, right: 16, zIndex: 2,
          background: "#fff", borderRadius: 50, padding: "6px 14px",
          display: "flex", alignItems: "center", gap: 6, boxShadow: "0 2px 10px rgba(0,0,0,0.12)",
          opacity: 1 - headerFade, transition: "opacity 0.05s linear" }}>
          <span style={{ fontWeight: 800, fontSize: 15, color: DARK }}>0</span>
        </div>
        <div style={{ position: "relative", zIndex: 1, opacity: 1 - headerFade, transition: "opacity 0.05s linear" }}>
          <div style={{ fontSize: 24, fontWeight: 800, color: "#fff", marginBottom: 6 }}>
            Bonjour {user?.name?.split(" ")[0] || "Yassine"} 
          </div>
        </div>
      </div>

      {/*  Niveau + Grade selectors (same style as profile)  */}
      <div ref={elastic.ref} style={{ padding: "42px 16px 0", background: HUB_BG, borderTopLeftRadius: 20, borderTopRightRadius: 20, position: "relative", zIndex: 1, marginTop: -20 }}>
        <div style={{ background: "#fff", borderRadius: 18, padding: "18px 20px", boxShadow: "0 2px 14px rgba(0,0,0,0.06)", ...elastic.style }}>
          <div style={{ fontSize: 13, fontWeight: 800, color: DARK, marginBottom: 16 }}>Choisir mon niveau et ma classe</div>

          {/* Niveau pills */}
          <div style={{ marginBottom: 16 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: "#aaa", letterSpacing: 1, textTransform: "uppercase", marginBottom: 8 }}>Niveau</div>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              {Object.entries(CURRICULUM).map(([key, val]) => {
                const isActive = niveau === key;
                return (
                  <button key={key}
                    onClick={() => { setNiveau(key); setGrade(null); setFiliere(null); setMatiere(null); setUnitIdx(null); }}
                    style={{
                      flex: 1, minWidth: 90, padding: "10px 8px", border: "none", borderRadius: 12, cursor: "pointer",
                      background: isActive ? val.color : "#F3F4F6",
                      color: isActive ? "#fff" : "#555",
                      fontWeight: isActive ? 800 : 600, fontSize: 12,
                      boxShadow: isActive ? `0 4px 12px ${val.color}44` : "none",
                      transition: "all 0.15s ease"
                    }}>
                    {val.label}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Classe pills — only shown when niveau is selected */}
          {niveau && (
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#aaa", letterSpacing: 1, textTransform: "uppercase", marginBottom: 8 }}>Classe</div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
                {CURRICULUM[niveau].grades.map(g => {
                  const isActive = grade?.id === g.id;
                  const col = CURRICULUM[niveau].color;
                  return (
                    <button key={g.id}
                      onClick={() => { setGrade(g); setFiliere(null); setMatiere(null); setUnitIdx(null); }}
                      style={{
                        padding: "10px 6px", border: "none", borderRadius: 12, cursor: "pointer",
                        background: isActive ? col : "#F3F4F6",
                        color: isActive ? "#fff" : "#555",
                        fontWeight: isActive ? 800 : 600, fontSize: 12,
                        boxShadow: isActive ? `0 4px 12px ${col}44` : "none",
                        transition: "all 0.15s ease", textAlign: "center"
                      }}>
                      {g.label}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* Filière picker — for TC, 1ère Bac and 2ème Bac */}
          {(grade?.id === "tc" || grade?.id === "1bac" || grade?.id === "2bac") && (
            <div style={{ marginTop: 16 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#aaa", letterSpacing: 1, textTransform: "uppercase", marginBottom: 8 }}>Filière / الشعبة</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {(grade.id === "tc" ? TC_FILIERES : grade.id === "1bac" ? BAC1_FILIERES : BAC2_FILIERES).map(f => {
                  const isActive = filiere?.id === f.id;
                  const col = CURRICULUM[niveau].color;
                  return (
                    <button key={f.id}
                      onClick={() => { setFiliere(f); setMatiere(null); setUnitIdx(null); }}
                      style={{
                        padding: "14px 16px", border: "none", borderRadius: 14, cursor: "pointer",
                        background: isActive ? col : "#F3F4F6",
                        color: isActive ? "#fff" : "#555",
                        fontWeight: isActive ? 800 : 600, fontSize: 13,
                        boxShadow: isActive ? `0 4px 14px ${col}55` : "none",
                        transition: "all 0.15s ease",
                        display: "flex", alignItems: "center", justifyContent: "space-between",
                        textAlign: "right"
                      }}>
                      <span style={{ flex: 1, textAlign: "center", fontWeight: isActive ? 800 : 600 }}>{f.label}</span>
                    </button>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* Next button */}
        {niveau && grade && (["tc","1bac","2bac"].includes(grade.id) ? filiere : true) && (
          <button className="cta-btn"
            onClick={() => setPage(3)}
            style={{
              width: "100%", marginTop: 16, padding: "16px", border: "none", borderRadius: 16,
              background: CURRICULUM[niveau].color, color: "#fff",
              fontWeight: 800, fontSize: 16, cursor: "pointer",
              boxShadow: `0 6px 0 ${CURRICULUM[niveau].color}88, 0 10px 20px ${CURRICULUM[niveau].color}44`,
              transition: "all 0.15s ease"
            }}>
            Suivant →
          </button>
        )}
      </div>

    </div>
  );

  //  PAGE 3: Matières 
  if (page === 3 && grade) {
    const mats = getMatieres();
    return (
      <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: HUB_BG,
        minHeight: "100vh", maxWidth: "100%", margin: "0 auto", paddingBottom: 120 }}>

        <GlobalStyles />
        {/* Purple header with grade pill */}
        <div style={{ background: `linear-gradient(160deg, ${PURPLE} 0%, ${PURPLE_DARK} 100%)`,
          padding: "0 20px", height: "25vh", display: "flex", flexDirection: "column", justifyContent: "center", position: "sticky", top: 0, zIndex: 0, overflow: "hidden", boxSizing: "border-box" }}>
          <HeroBg />
          <div style={{ position: "absolute", inset: 0, background: HUB_BG, opacity: headerFade, pointerEvents: "none", transition: "opacity 0.05s linear" }} />

          <div style={{ position: "relative", zIndex: 1, opacity: 1 - headerFade, transition: "opacity 0.05s linear" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14, direction: "ltr" }}>
              {/* Streak pill right-aligned */}
              <div style={{ marginLeft: "auto", background: "#fff", borderRadius: 50,
                padding: "5px 12px", display: "flex", alignItems: "center", gap: 5,
                boxShadow: "0 2px 8px rgba(0,0,0,0.15)" }}>
                <span style={{ fontWeight: 800, fontSize: 14, color: DARK }}>0</span>
              </div>
            </div>
            <div style={{ color: "#fff", fontSize: 22, fontWeight: 800 }}>Bonjour {user?.name?.split(" ")[0] || "Yassine"} </div>
          </div>
        </div>

        {/* Subject list */}
        <div ref={elastic.ref} style={{ padding: "38px 16px 0", background: HUB_BG, borderTopLeftRadius: 20, borderTopRightRadius: 20, position: "relative", zIndex: 1, marginTop: -20 }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: "#999", letterSpacing: 1,
            textTransform: "uppercase", marginBottom: 14 }}>Matières</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 14, ...elastic.style }}>
            {mats.map((m) => {
              const data = getData(m.id);
              const totalLessons = data ? data.units.reduce((a, u) => a + u.lessons.length, 0) : null;
              const art = SUBJECT_ART[m.id] || { emoji: m.icon, bg: m.color + "22" };
              return (
                <SubjectCard key={m.id} m={m} art={art} data={data} totalLessons={totalLessons}
                  onClick={() => {
                    setMatiere(m);
                    const d = getData(m.id);
                    // If data has exactly one unit with no title, skip the units page
                    if (d && d.units.length === 1 && !d.units[0].title) {
                      setUnitIdx(0); setPage(5);
                    } else {
                      setUnitIdx(null); setPage(4);
                    }
                  }} />
              );
            })}
          </div>
        </div>

        <BottomNav active="matieres" />
      </div>
    );
  }

  //  PAGE 4: Units list 
  if (page === 4 && matiere) {
    const data = getData(matiere.id);
    const isRTL4 = subjectIsRTL(matiere?.id);
    if (!data) {
      return (
        <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: HUB_BG, minHeight: "100vh", maxWidth: "100%", margin: "0 auto", paddingBottom: 120 }}>
          <GlobalStyles />
          <InnerHeader title={matiere.label}
            onBack={() => setPage(3)} color={matiere.color} isRTL={isRTL4} matiereId={matiere.id} />
          <div ref={elastic.ref} style={{ padding: "40px 18px", textAlign: "center", color: "#aaa", marginTop: -20, background: HUB_BG, borderTopLeftRadius: 20, borderTopRightRadius: 20, position: "relative", zIndex: 1 }}>
            <div style={{ fontSize: 48, marginTop: 20 }}></div>
            <div style={{ fontSize: 16, fontWeight: 700, color: DARK, marginTop: 12 }}>Contenu bientôt disponible</div>
            <div style={{ fontSize: 13, marginTop: 6 }}>Le contenu détaillé sera ajouté prochainement.</div>
          </div>
          <BottomNav active="matieres" />
        </div>
      );
    }
    return (
      <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: HUB_BG, minHeight: "100vh", maxWidth: "100%", margin: "0 auto", paddingBottom: 120, direction: isRTL4 ? "rtl" : "ltr" }}>
        <GlobalStyles />
        <InnerHeader title={matiere.label}
          onBack={() => setPage(3)} color={matiere.color} isRTL={isRTL4} matiereId={matiere.id} />
        <div ref={elastic.ref} style={{ padding: "28px 18px 24px", background: HUB_BG, borderTopLeftRadius: 20, borderTopRightRadius: 20, position: "relative", zIndex: 1, marginTop: -20 }}>
          <div style={{ display: "flex", flexDirection: "column", gap: 12, ...elastic.style }}>
            {data.units.map((unit, i) => (
              <button key={i} className="unit-card" onClick={() => { setUnitIdx(i); setPage(5); }}
                style={{ background: "#fff", border: "none", borderRadius: 16,
                  padding: "16px 18px", cursor: "pointer", textAlign: isRTL4 ? "right" : "left",
                  boxShadow: "0 2px 12px rgba(124,58,237,0.07)", display: "flex", alignItems: "center", gap: 14, direction: isRTL4 ? "rtl" : "ltr" }}>
                <div style={{ width: 50, height: 50, borderRadius: 13, flexShrink: 0,
                  background: `linear-gradient(135deg, ${data.color}, ${data.color}BB)`,
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: 18, fontWeight: 900, color: "#fff" }}>{i + 1}</div>
                <div style={{ flex: 1, textAlign: isRTL4 ? "right" : "left" }}>
                  <div style={{ fontSize: 13, fontWeight: 800, color: DARK, lineHeight: 1.3 }}>{unit.title || (isRTL4 ? `الوحدة ${i + 1}` : `Unité ${i + 1}`)}</div>
                  <div style={{ fontSize: 11, color: "#aaa", marginTop: 4 }}>{unit.lessons.length} {isRTL4 ? "درس" : "cours"}</div>
                </div>
                <span style={{ color: data.color, fontSize: 18 }}>{isRTL4 ? "‹" : "›"}</span>
              </button>
            ))}
          </div>
        </div>
        <BottomNav active="matieres" />
      </div>
    );
  }

  //  PAGE 5: Lessons list 
  // Static lesson loader — looks up content from the CONTENT object above.
  // To add content for a lesson, add an entry to CONTENT[gradeId][subjectId][lessonTitle].
  const loadLesson = (lessonTitle) => {
    const gradeId = grade?.id ?? "";
    const subjectId = matiere?.id ?? "";
    const entry = getContent(gradeId, subjectId, lessonTitle);
    if (entry) {
      setLessonContent(entry);
      setLessonError(null);
      onLessonOpened();
    } else {
      setLessonContent(null);
      setLessonError("__not_found__");
    }
    setLessonLoading(false);
  };

  // Static exercises loader — exercises live inside CONTENT[grade][subject][lesson].exercises
  const loadExercises = (lessonTitle) => {
    const gradeId = grade?.id ?? "";
    const subjectId = matiere?.id ?? "";
    const entry = getContent(gradeId, subjectId, lessonTitle);
    setAnswers({});
    setChecked(false);
    setExercisesLoading(false);
    if (entry?.exercises) {
      setExercises(entry.exercises);
      setExercisesError(null);
    } else {
      setExercises(null);
      setExercisesError("__not_found__");
    }
  };

  //  PAGE 5 helpers 
  const _getCurrentUnit = () => {
    if (!matiere || unitIdx === null) return null;
    const d = getData(matiere.id);
    return d ? d.units[unitIdx] : null;
  };

  const handleLessonClick = (lesson, i) => {
    setLessonIdx(i);
    setExercises(null);
    setExercisesError(null);
    setAnswers({});
    setChecked(false);
    setLessonContent(null);
    setLessonError(null);
    setActiveTab("lecon");
    setPage(6);
    loadLesson(lesson);
  };

  const handleTabSwitch = (tab) => {
    if (tab === activeTab) return;
    setActiveTab(tab);
    const unit = _getCurrentUnit();
    const lesson = lessonIdx !== null && unit ? unit.lessons[lessonIdx] : "";
    if (tab === "exercices" && !exercises && !exercisesLoading) {
      loadExercises(lesson);
    }
  };

  //  PAGE 5: Lessons list 
  if (page === 5 && matiere && unitIdx !== null) {
    const data = getData(matiere.id);
    const unit = data.units[unitIdx];
    const isRTL5 = subjectIsRTL(matiere?.id);

    return (
      <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: HUB_BG, minHeight: "100vh", maxWidth: "100%", margin: "0 auto", direction: isRTL5 ? "rtl" : "ltr", paddingBottom: 120 }}>
        <GlobalStyles />
        <InnerHeader title={unit.title || matiere.label}
          onBack={() => {
            if (!unit.title) { setPage(3); } else { setUnitIdx(null); setPage(4); }
          }} color={data.color} isRTL={isRTL5} matiereId={matiere.id} />
        <div ref={elastic.ref} style={{ padding: "28px 18px 24px", background: HUB_BG, borderTopLeftRadius: 20, borderTopRightRadius: 20, position: "relative", zIndex: 1, marginTop: -20 }}>
          <div style={{ display: "flex", flexDirection: "column", gap: 9, ...elastic.style }}>
            {unit.lessons.map((lesson, i) => {
              const { tag, text } = parseLesson(lesson);
              const tagColor = tag ? (TAG_COLORS[tag] || data.color) : data.color;
              return (
                <LessonRow key={i} lesson={lesson} i={i} tag={tag} text={text} tagColor={tagColor}
                  isRTL={isRTL5} onClick={() => handleLessonClick(lesson, i)} />
              );
            })}
          </div>
        </div>
        <BottomNav active="matieres" />
      </div>
    );
  }

  //  PAGE 6: Activity hub (card grid like screenshot) 
  if (page === 6 && matiere && unitIdx !== null) {
    const data = getData(matiere.id);
    const unit = data.units[unitIdx];
    const lesson = lessonIdx !== null ? unit.lessons[lessonIdx] : "";
    const { tag, text } = parseLesson(lesson);
    const tagColor = tag ? (TAG_COLORS[tag] || data.color) : data.color;
    const hubBg = HUB_BG; // warm cream like screenshot

    //  SVG icons matching the screenshot style 
    const IconBook = ({ color }) => (
      <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/>
      </svg>
    );
    const IconPencil = ({ color }) => (
      <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/><path d="m15 5 4 4"/>
      </svg>
    );
    const IconQuiz = ({ color }) => (
      <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <rect x="3" y="3" width="8" height="8" rx="1"/><rect x="13" y="3" width="8" height="8" rx="1"/>
        <rect x="3" y="13" width="8" height="8" rx="1"/>
        <path d="M17 13v2m0 4v.01M15 17h4"/>
      </svg>
    );
    const IconRevision = ({ color }) => (
      <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
        <polyline points="14 2 14 8 20 8"/><line x1="9" y1="13" x2="15" y2="13"/><line x1="9" y1="17" x2="12" y2="17"/>
      </svg>
    );
    const IconVideo = ({ color }) => (
      <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="12" cy="12" r="10"/><polygon points="10 8 16 12 10 16 10 8"/>
      </svg>
    );
    const IconStudygram = ({ color }) => (
      <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.5-3.5L9 20"/>
      </svg>
    );
    const IconTrophy = ({ color }) => (
      <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <path d="M8 21h8"/><path d="M12 17v4"/><path d="M7 4h10v5a5 5 0 0 1-10 0Z"/>
        <path d="M17 5h2a2 2 0 0 1 0 4h-2"/><path d="M7 5H5a2 2 0 0 0 0 4h2"/>
      </svg>
    );
    const IconFlashcards = ({ color }) => (
      <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
        <rect x="3" y="5" width="13" height="16" rx="2" transform="rotate(-8 9.5 13)"/>
        <path d="M14 9.5h.01"/><path d="M14 13.5h.01"/>
      </svg>
    );

    //  RTL/LTR for this lesson 
    const isRTL = subjectIsRTL(matiere?.id);
    const dir = isRTL ? "rtl" : "ltr";
    const arrowFlip = isRTL ? "scaleX(-1)" : "none";

    //  Hub card grid 
    const hasContent = !!getContent(grade?.id ?? "", matiere?.id ?? "", lesson);
    const hasExercises = hasContent && !!getContent(grade?.id ?? "", matiere?.id ?? "", lesson)?.exercises;
    const totalQuizQuestions = hasExercises ? getContent(grade?.id ?? "", matiere?.id ?? "", lesson)?.exercises?.exercises?.length ?? 10 : 10;

    const HUB_CARDS = [
      { key: "cours",      label: "Cours",      Icon: IconBook,       color: "#C084A8", bg: "#F3E8EE", available: hasContent },
      { key: "video",      label: "Vidéo",      Icon: IconVideo,      color: "#C084A8", bg: "#F3E8EE", available: false },
      { key: "revision",   label: "Révision",   Icon: IconRevision,   color: "#C084A8", bg: "#F3E8EE", available: false },
      { key: "studygram",  label: "Studygram",  Icon: IconStudygram,  color: "#C084A8", bg: "#F3E8EE", available: false },
      { key: "quiz",       label: "Quiz",       Icon: IconQuiz,       color: "#7C6FCD", bg: "#EEEAF8", available: false, badge: `--/${totalQuizQuestions}` },
      { key: "exercices",  label: "Exercices",  Icon: IconPencil,     color: "#7C6FCD", bg: "#EEEAF8", available: hasExercises },
      { key: "defis",      label: "Défis",      Icon: IconTrophy,     color: "#7C6FCD", bg: "#EEEAF8", available: false },
      { key: "flashcards", label: "Flashcards", Icon: IconFlashcards, color: "#7C6FCD", bg: "#EEEAF8", available: false, badge: "--/10" },
    ];

    //  Sub-page: Cours content 
    if (activeTab === "cours") {
      const lessonEntry = getContent(grade?.id ?? "", matiere?.id ?? "", lesson);
      const lc = lessonEntry;
      if (!lc) return (
        <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: hubBg, minHeight: "100vh", maxWidth: "100%", margin: "0 auto" }}>
          <GlobalStyles />
          <div style={{ background: tagColor, padding: "0 20px", height: "25vh", display: "flex", flexDirection: "column", justifyContent: "center", position: "sticky", top: 0, zIndex: 0, boxSizing: "border-box" }}>
            <div style={{ position: "absolute", inset: 0, background: HUB_BG, opacity: headerFade, pointerEvents: "none", transition: "opacity 0.05s linear" }} />
            <button onClick={() => setActiveTab("hub")} style={{ position: "absolute", top: 14, left: 16, zIndex: 2, background: "#fff", border: "none", borderRadius: 50, width: 40, height: 40, cursor: "pointer", boxShadow: "0 2px 10px rgba(0,0,0,0.12)", display: "flex", alignItems: "center", justifyContent: "center" }}><img src={BACK_ICON_SRC} alt="back" style={{ width: 18, height: 18 }} /></button>
            <div style={{ position: "relative", zIndex: 1, color: "#fff", fontSize: 18, fontWeight: 800, marginTop: 6, textAlign: "center", opacity: 1 - headerFade, transition: "opacity 0.05s linear" }}>{text}</div>
          </div>
          <div ref={elastic.ref} style={{ padding: "24px 24px", textAlign: "center", color: "#aaa", marginTop: -20, background: HUB_BG, borderTopLeftRadius: 20, borderTopRightRadius: 20, position: "relative", zIndex: 1 }}>
            <div style={{ fontSize: 48, marginTop: 20 }}></div>
            <div style={{ fontSize: 15, fontWeight: 700, color: DARK, marginTop: 12 }}>Cours bientôt disponible</div>
          </div>
        </div>
      );

      return (
        <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: HUB_BG, minHeight: "100vh", maxWidth: "100%", margin: "0 auto", direction: dir }}>
          <GlobalStyles />
          {/* Header */}
          <div style={{ background: tagColor, padding: "0 20px", height: "25vh", display: "flex", flexDirection: "column", justifyContent: "center", position: "sticky", top: 0, zIndex: 0, overflow: "hidden", boxSizing: "border-box" }}>
            <HeroBg color={tagColor} />
            <div style={{ position: "absolute", inset: 0, background: HUB_BG, opacity: headerFade, pointerEvents: "none", transition: "opacity 0.05s linear" }} />
            <button onClick={() => setActiveTab("hub")} style={{ position: "absolute", top: 14, left: 16, zIndex: 2, background: "#fff", border: "none", borderRadius: 50, width: 40, height: 40, cursor: "pointer", boxShadow: "0 2px 10px rgba(0,0,0,0.12)", display: "flex", alignItems: "center", justifyContent: "center" }}><img src={BACK_ICON_SRC} alt="back" style={{ width: 18, height: 18 }} /></button>
            {tag && <div style={{ position: "relative", zIndex: 1, fontSize: 10, fontWeight: 800, color: "rgba(255,255,255,0.8)", textTransform: "uppercase", letterSpacing: 1, marginBottom: 4, textAlign: "center", opacity: 1 - headerFade, transition: "opacity 0.05s linear" }}>{tag}</div>}
            <div style={{ position: "relative", zIndex: 1, color: "#fff", fontSize: 17, fontWeight: 800, lineHeight: 1.35, direction: dir, textAlign: "center", opacity: 1 - headerFade, transition: "opacity 0.05s linear" }}>{text}</div>
          </div>

          <div ref={elastic.ref} style={{ padding: "40px 20px 40px", direction: dir, textAlign: isRTL ? "right" : "left", background: HUB_BG, borderTopLeftRadius: 20, borderTopRightRadius: 20, position: "relative", zIndex: 1, marginTop: -20 }}>
            <style>{`
              .lc-h2 { font-size: 20px; font-weight: 800; color: #1A1A2E; margin: 0 0 10px; text-align: ${isRTL ? "right" : "left"}; direction: ${dir}; }
              .lc-para { font-size: 14px; color: #2D2D3A; line-height: 1.75; margin: 0 0 6px; text-align: ${isRTL ? "right" : "left"}; direction: ${dir}; unicode-bidi: plaintext; }
              .lc-star-row { display: flex; flex-direction: ${isRTL ? "row-reverse" : "row"}; align-items: flex-start; gap: 10px; margin: 8px 0 4px; direction: ${dir}; }
              .lc-star { font-size: 15px; color: #555; flex-shrink: 0; margin-top: 2px; }
              .lc-star-text { font-size: 14px; color: #2D2D3A; line-height: 1.6; text-align: ${isRTL ? "right" : "left"}; direction: ${dir}; flex: 1; }
              .lc-arrow-row { display: flex; flex-direction: ${isRTL ? "row-reverse" : "row"}; align-items: flex-start; gap: 8px; ${isRTL ? "margin-right:20px" : "margin-left:20px"}; margin-top: 5px; margin-bottom: 5px; direction: ${dir}; }
              .lc-arrow { font-size: 18px; color: #333; flex-shrink: 0; display: inline-block; transform: ${arrowFlip}; }
              .lc-arrow-text { font-size: 14px; font-weight: 700; color: #1A1A2E; line-height: 1.55; text-align: ${isRTL ? "right" : "left"}; direction: ${dir}; flex: 1; }
              .lc-divider { height: 1px; background: #ECECEC; margin: 18px 0; }
              .lc-sec-title { font-size: 15px; font-weight: 800; color: ${tagColor}; margin: 0 0 10px; display: flex; flex-direction: ${isRTL ? "row-reverse" : "row"}; align-items: center; gap: 8px; direction: ${dir}; }
              .lc-num { width: 24px; height: 24px; border-radius: 50%; background: ${tagColor}; color: #fff; display: inline-flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 900; flex-shrink: 0; }
              .lc-retenir { background: ${tagColor}12; border: 1.5px solid ${tagColor}35; border-radius: 14px; padding: 16px 18px; text-align: ${isRTL ? "right" : "left"}; direction: ${dir}; }
              .lc-retenir-pill { display: inline-flex; align-items: center; gap: 6px; flex-direction: ${isRTL ? "row-reverse" : "row"}; background: ${tagColor}; color: #fff; border-radius: 20px; padding: 4px 12px; font-size: 13px; font-weight: 800; margin-bottom: 10px; }
              .lc-exemple-pill { display: inline-flex; align-items: center; gap: 6px; background: ${tagColor}; color: #fff; border-radius: 20px; padding: 5px 14px 5px 10px; font-size: 14px; font-weight: 800; margin-bottom: 12px; }
              .lc-exemple-box { border-${isRTL ? "right" : "left"}: 3px dashed #ccc; padding: ${isRTL ? "6px 16px 6px 0" : "6px 0 6px 16px"}; margin-${isRTL ? "right" : "left"}: 4px; direction: ${dir}; text-align: ${isRTL ? "right" : "left"}; }
              .lc-astuce-pill { display: inline-flex; align-items: center; gap: 6px; flex-direction: ${isRTL ? "row-reverse" : "row"}; background: #F59E0B; color: #fff; border-radius: 20px; padding: 5px 14px; font-size: 14px; font-weight: 800; margin-bottom: 12px; }
              .lc-astuce-box { background: #FFFBEB; border: 1.5px solid #FDE68A; border-radius: 14px; padding: 14px 16px; text-align: ${isRTL ? "right" : "left"}; direction: ${dir}; }
            `}</style>

            {/* Objective */}
            <div style={{ background: `${tagColor}12`, borderRadius: 12, padding: "10px 14px", marginBottom: 20, border: `1px solid ${tagColor}30`, display: "flex", flexDirection: isRTL ? "row-reverse" : "row", alignItems: "center", gap: 10 }}>
              <span style={{ fontSize: 18, flexShrink: 0 }}></span>
              <span style={{ fontSize: 13, fontWeight: 700, color: tagColor, lineHeight: 1.5, direction: dir, textAlign: isRTL ? "right" : "left" }}>{lc.objective}</span>
            </div>

            {/* Introduction */}
            <h2 className="lc-h2">{isRTL ? "مقدمة" : "Introduction"}</h2>
            <p className="lc-para" style={{ direction: dir }}>{lc.introduction}</p>

            {/* Sections */}
            {(lc.sections || []).map((sec, i) => (
              <div key={i}>
                <div className="lc-divider" />
                <div className="lc-sec-title">
                  <span className="lc-num">{i + 1}</span>
                  <span style={{ direction: dir }}>{sec.heading}</span>
                </div>
                {sec.content && <p className="lc-para" style={{ direction: dir }}>{sec.content}</p>}
                {(sec.bullets || []).map((b, bi) => (
                  <div key={bi}>
                    <div style={{ display: "flex", flexDirection: "row", alignItems: "flex-start", gap: 10, margin: "8px 0 4px", direction: dir }}>
                      {isRTL ? (
                        <>
                          <span style={{ fontSize: 14, color: "#2D2D3A", lineHeight: 1.6, flex: 1, textAlign: "right" }}>{b}</span>
                          <span style={{ fontSize: 15, color: "#555", flexShrink: 0, marginTop: 2 }}></span>
                        </>
                      ) : (
                        <>
                          <span style={{ fontSize: 15, color: "#555", flexShrink: 0, marginTop: 2 }}></span>
                          <span style={{ fontSize: 14, color: "#2D2D3A", lineHeight: 1.6, flex: 1, textAlign: "left" }}>{b}</span>
                        </>
                      )}
                    </div>
                    {sec.subBullets?.[bi]?.map((sub, si) => (
                      <div key={si} style={{ display: "flex", flexDirection: "row", alignItems: "flex-start", gap: 8, marginTop: 5, marginBottom: 5, direction: dir, ...(isRTL ? { marginRight: 20 } : { marginLeft: 20 }) }}>
                        {isRTL ? (
                          <>
                            <span style={{ fontSize: 14, fontWeight: 700, color: "#1A1A2E", lineHeight: 1.55, flex: 1, textAlign: "right" }}>{sub}</span>
                            <span style={{ fontSize: 18, color: "#333", flexShrink: 0, display: "inline-block", transform: "scaleX(-1)" }}></span>
                          </>
                        ) : (
                          <>
                            <span style={{ fontSize: 18, color: "#333", flexShrink: 0 }}></span>
                            <span style={{ fontSize: 14, fontWeight: 700, color: "#1A1A2E", lineHeight: 1.55, flex: 1, textAlign: "left" }}>{sub}</span>
                          </>
                        )}
                      </div>
                    ))}
                  </div>
                ))}
                {sec.diagram === "division" && (
                  <div style={{ display: "flex", justifyContent: "center", margin: "18px 0 6px", direction: "ltr", unicodeBidi: "bidi-override" }}>
                    <div style={{ display: "flex", flexDirection: "row", alignItems: "center", gap: 22, direction: "ltr", unicodeBidi: "bidi-override" }}>
                      <div style={{ display: "flex", flexDirection: "column", gap: 28, alignItems: "flex-end" }}>
                        <span style={{ fontFamily: "Georgia, serif", fontStyle: "italic", fontSize: 40, fontWeight: 700, color: "#3B82F6" }}>a</span>
                        <span style={{ fontFamily: "Georgia, serif", fontStyle: "italic", fontSize: 36, fontWeight: 700, color: "#F59E0B" }}>r</span>
                      </div>
                      <div style={{ display: "flex", flexDirection: "column", alignItems: "stretch", height: 130 }}>
                        <div style={{ flex: 1, borderRight: "2.5px solid #134E4A" }} />
                        <div style={{ flex: 1, borderRight: "2.5px solid #134E4A" }} />
                      </div>
                      <div style={{ display: "flex", flexDirection: "column", gap: 6, alignItems: "flex-start" }}>
                        <span style={{ fontFamily: "Georgia, serif", fontStyle: "italic", fontSize: 40, fontWeight: 700, color: "#10B981" }}>b</span>
                        <div style={{ width: 56, borderTop: "2.5px solid #134E4A", marginTop: 14, marginBottom: 14 }} />
                        <span style={{ fontFamily: "Georgia, serif", fontStyle: "italic", fontSize: 40, fontWeight: 700, color: "#7C3AED", alignSelf: "flex-end" }}>q</span>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ))}

            {/* Star row (introductory bullet before examples) */}
            {lc.starRow && (
              <div style={{ display: "flex", flexDirection: "row", alignItems: "flex-start", gap: 10, margin: "8px 0 4px", direction: dir }}>
                {isRTL ? (
                  <>
                    <span style={{ fontSize: 14, color: "#2D2D3A", lineHeight: 1.6, flex: 1, textAlign: "right" }}>{lc.starRow}</span>
                    <span style={{ fontSize: 15, color: "#555", flexShrink: 0, marginTop: 2 }}></span>
                  </>
                ) : (
                  <>
                    <span style={{ fontSize: 15, color: "#555", flexShrink: 0, marginTop: 2 }}></span>
                    <span style={{ fontSize: 14, color: "#2D2D3A", lineHeight: 1.6, flex: 1, textAlign: "left" }}>{lc.starRow}</span>
                  </>
                )}
              </div>
            )}

            {/* Rich worked examples with division boxes */}
            {(lc.examples || []).map((ex, ei) => (
              <div key={ei}>
                <div className="lc-divider" />
                {/* Exemple pill */}
                <div className="lc-exemple-pill" style={{ direction: "ltr" }}>
                  <span style={{ fontSize: 17 }}></span>
                  <span style={{ fontFamily: "Georgia,serif", fontWeight: 900, fontSize: 16 }}>{ex.label}</span>
                  {isRTL ? "مثال" : "Exemple"}
                </div>
                {/* Intro */}
                <p className="lc-para" style={{ direction: dir, marginBottom: 10 }}>{ex.intro}</p>

                {/* Step rows */}
                {(ex.steps || []).map((step, si) => (
                  step.style === "formula"
                    ? <p key={si} style={{ fontSize: 12, color: "#555", textAlign: "center", margin: "6px 0 4px", direction: "ltr" }}>{step.text}</p>
                    : <p key={si} className="lc-para" style={{ direction: dir, marginBottom: 4 }}>{step.text}</p>
                ))}

                {/* Simple division box: dividend | divisor \n -sub | line \n rem | quotient */}
                {ex.divisionBox && (() => {
                  const db = ex.divisionBox;
                  return (
                    <div style={{ display: "flex", justifyContent: "center", margin: "16px 0 10px", direction: "ltr" }}>
                      <div style={{ border: "none", display: "inline-block" }}>
                        {/* Top row: dividend | divisor */}
                        <div style={{ display: "flex", alignItems: "stretch" }}>
                          <div style={{ fontSize: 32, fontWeight: 700, color: "#3B82F6", padding: "4px 16px 4px 8px", minWidth: 64, textAlign: "center" }}>{db.dividend}</div>
                          <div style={{ width: 2, background: "#134E4A", alignSelf: "stretch" }} />
                          <div style={{ fontSize: 32, fontWeight: 700, color: "#10B981", padding: "4px 8px 4px 16px", minWidth: 56 }}>{db.divisor}</div>
                        </div>
                        {/* Second row: -subtracted | line | quotient */}
                        <div style={{ display: "flex", alignItems: "flex-start" }}>
                          <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", padding: "0 16px 0 8px", minWidth: 64 }}>
                            <div style={{ fontSize: 28, fontWeight: 700, color: "#1A1A2E" }}>-{db.subtracted}</div>
                            <div style={{ width: "100%", borderTop: "2px solid #134E4A", marginTop: 2 }} />
                            <div style={{ fontSize: 30, fontWeight: 700, color: "#F59E0B", marginTop: 4 }}>{db.remainder}</div>
                          </div>
                          <div style={{ width: 2, background: "#134E4A", minHeight: 80 }} />
                          <div style={{ padding: "4px 8px 0 16px" }}>
                            <div style={{ width: 48, borderTop: "2px solid #134E4A", marginBottom: 6 }} />
                            <div style={{ fontSize: 30, fontWeight: 700, color: "#7C3AED" }}>{db.quotient}</div>
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })()}

                {/* Long division box for multi-step */}
                {ex.divisionBoxLong && (() => {
                  const db = ex.divisionBoxLong;
                  return (
                    <div style={{ display: "flex", justifyContent: "center", margin: "16px 0 10px", direction: "ltr" }}>
                      <div style={{ display: "inline-block" }}>
                        {/* Top row: dividend | divisor */}
                        <div style={{ display: "flex", alignItems: "stretch" }}>
                          <div style={{ fontSize: 30, fontWeight: 700, color: "#3B82F6", padding: "4px 16px 4px 8px", minWidth: 72, textAlign: "center" }}>{db.dividend}</div>
                          <div style={{ width: 2, background: "#134E4A", alignSelf: "stretch" }} />
                          <div style={{ fontSize: 30, fontWeight: 700, color: "#10B981", padding: "4px 8px 4px 16px", minWidth: 52 }}>{db.divisor}</div>
                        </div>
                        {/* Steps */}
                        {(db.steps || []).map((s, si) => (
                          <div key={si} style={{ display: "flex", alignItems: "flex-start" }}>
                            <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", padding: "0 16px 0 8px", minWidth: 72 }}>
                              <div style={{ fontSize: 24, fontWeight: 700, color: "#1A1A2E" }}>-{s.sub}</div>
                              <div style={{ width: "100%", borderTop: "2px solid #134E4A", marginTop: 2 }} />
                              <div style={{ fontSize: 24, fontWeight: 700, color: "#F59E0B", marginTop: 2 }}>{s.down}</div>
                              <div style={{ fontSize: 24, fontWeight: 700, color: "#1A1A2E" }}>-{s.sub2}</div>
                              <div style={{ width: "100%", borderTop: "2px solid #134E4A", marginTop: 2 }} />
                              <div style={{ fontSize: 24, fontWeight: 700, color: "#F59E0B", marginTop: 2 }}>{s.rem}</div>
                            </div>
                            <div style={{ width: 2, background: "#134E4A", minHeight: 160 }} />
                            <div style={{ padding: "4px 8px 0 16px" }}>
                              <div style={{ width: 44, borderTop: "2px solid #134E4A", marginBottom: 6 }} />
                              <div style={{ fontSize: 26, fontWeight: 700, color: "#7C3AED" }}>{db.quotient}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  );
                })()}

                {/* Conclusion arrow row */}
                {ex.conclusion && (
                  <div style={{ display: "flex", flexDirection: "row", alignItems: "flex-start", gap: 8, marginTop: 10, direction: dir, ...(isRTL ? { marginRight: 0 } : { marginLeft: 0 }) }}>
                    {isRTL ? (
                      <>
                        <span style={{ fontSize: 14, fontWeight: 700, color: "#1A1A2E", lineHeight: 1.55, flex: 1, textAlign: "right" }}>{ex.conclusion}</span>
                        <span style={{ fontSize: 18, color: "#333", flexShrink: 0, display: "inline-block", transform: "scaleX(-1)" }}></span>
                      </>
                    ) : (
                      <>
                        <span style={{ fontSize: 18, color: "#333", flexShrink: 0 }}></span>
                        <span style={{ fontSize: 14, fontWeight: 700, color: "#1A1A2E", lineHeight: 1.55, flex: 1, textAlign: "left" }}>{ex.conclusion}</span>
                      </>
                    )}
                  </div>
                )}
                {/* Formula */}
                {ex.formula && (
                  <div style={{ textAlign: "center", marginTop: 10, marginBottom: 4 }}>
                    <span style={{ fontSize: 15, fontWeight: 700, color: "#3B82F6", direction: "ltr", display: "inline-block" }}>
                      {ex.formula.split(/(\d+)/g).map((part, pi) =>
                        /^\d+$/.test(part)
                          ? <span key={pi} style={{ color: ["#3B82F6","#10B981","#7C3AED","#F59E0B","#F59E0B","#7C3AED","#10B981","#3B82F6"][pi % 8] }}>{part}</span>
                          : <span key={pi} style={{ color: "#1A1A2E" }}>{part}</span>
                      )}
                    </span>
                  </div>
                )}
              </div>
            ))}

            {/* Key Points */}
            {lc.keyPoints?.length > 0 && (
              <div>
                <div className="lc-divider" />
                <div className="lc-retenir">
                  <div className="lc-retenir-pill"><span style={{ fontSize: 16 }}></span>{isRTL ? "ما يجب حفظه" : "À retenir"}</div>
                  {lc.keyPoints.map((pt, i) => (
                    <div key={i} style={{ display: "flex", flexDirection: "row", alignItems: "flex-start", gap: 10, marginTop: i === 0 ? 0 : 8, direction: dir }}>
                      {isRTL ? (
                        <>
                          <span style={{ fontSize: 14, color: "#2D2D3A", lineHeight: 1.6, flex: 1, textAlign: "right" }}>{pt}</span>
                          <span style={{ fontSize: 15, color: "#555", flexShrink: 0, marginTop: 2 }}></span>
                        </>
                      ) : (
                        <>
                          <span style={{ fontSize: 15, color: "#555", flexShrink: 0, marginTop: 2 }}></span>
                          <span style={{ fontSize: 14, color: "#2D2D3A", lineHeight: 1.6, flex: 1, textAlign: "left" }}>{pt}</span>
                        </>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Example */}
            {lc.example && (
              <div>
                <div className="lc-divider" />
                <div className="lc-exemple-pill"><span style={{ fontSize: 17 }}></span>{isRTL ? "مثال" : "Exemple"}</div>
                <div className="lc-exemple-box">
                  <p className="lc-para" style={{ direction: dir }}>{lc.example}</p>
                </div>
              </div>
            )}

            {/* Astuce */}
            {lc.astuce && (
              <div>
                <div className="lc-divider" />
                <div className="lc-astuce-pill"><span style={{ fontSize: 16 }}></span>{isRTL ? "ملاحظة" : "Astuce"}</div>
                <div className="lc-astuce-box">
                  {(Array.isArray(lc.astuce) ? lc.astuce : [lc.astuce]).map((line, i) => (
                    <p key={i} className="lc-para" style={{ direction: dir, marginBottom: i === (Array.isArray(lc.astuce) ? lc.astuce.length - 1 : 0) ? 0 : 6 }}>{line}</p>
                  ))}
                </div>
              </div>
            )}

            {/* Go to exercises */}
            {hasExercises && (
              <button onClick={() => { setActiveTab("exercices"); loadExercises(lesson); }}
                className="cta-btn"
                style={{ marginTop: 28, width: "100%", background: `linear-gradient(135deg, ${tagColor}, ${tagColor}CC)`,
                  color: "#fff", border: "none", borderRadius: 14, padding: "15px", cursor: "pointer",
                  fontWeight: 800, fontSize: 15, boxShadow: `0 4px 15px ${tagColor}44` }}>
                {isRTL ? " انتقل إلى التمارين" : " Passer aux exercices"}
              </button>
            )}
          </div>
        </div>
      );
    }

    //  Sub-page: Exercices — full-screen quiz matching screenshot 
    if (activeTab === "exercices") {
      const [qIdx,     setQIdx]     = useState(0);
      const [selected, setSelected] = useState(null);
      const [revealed, setRevealed] = useState(false);
      const [allAns,   setAllAns]   = useState({});
      const [quizDone, setQuizDone] = useState(false);

      const exList   = exercises?.exercises || [];
      const totalQ   = exList.length;
      const currentQ = exList[qIdx] || null;
      const correct  = (currentQ?.answer || "").trim().toLowerCase();
      const selIsOk  = revealed && (selected || "").trim().toLowerCase() === correct;
      const selIsBad = revealed && selected && !selIsOk;

      const finalScore = exList.reduce((acc, ex, i) => {
        const a = (allAns[i] || "").trim().toLowerCase();
        return acc + (a === (ex.answer || "").trim().toLowerCase() ? 1 : 0);
      }, 0);

      //  Results screen 
      if (quizDone) {
        const pct = Math.round((finalScore / totalQ) * 100);
        return (
          <div style={{ fontFamily:"'Segoe UI',system-ui,sans-serif", minHeight:"100vh",
            background:tagColor, position:"relative", overflow:"hidden",
            display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center",
            padding:"40px 24px", direction:dir }}>
            <GlobalStyles />
            <div style={{ position:"absolute", top:160, left:-100, width:200, height:200, borderRadius:"50%", background:"rgba(255,255,255,0.06)", pointerEvents:"none" }}/>
            <svg style={{ position:"absolute", bottom:0, left:0, width:"100%", pointerEvents:"none" }} viewBox="0 0 430 110" preserveAspectRatio="none">
              <path d="M0,75 Q50,40 110,65 Q170,90 230,50 Q290,10 350,45 Q400,70 430,40 L430,110 L0,110 Z" fill="rgba(0,0,0,0.18)"/>
              <path d="M0,92 Q70,65 140,85 Q210,105 280,72 Q350,40 430,65 L430,110 L0,110 Z" fill="rgba(0,0,0,0.25)"/>
            </svg>
            <div style={{ position:"relative", zIndex:1, textAlign:"center", width:"100%" }}>
              <div style={{ fontSize:72, marginBottom:12 }}>{pct>=80?"":pct>=50?"":""}</div>
              <div style={{ color:"#fff", fontSize:34, fontWeight:900, marginBottom:6 }}>{finalScore} / {totalQ}</div>
              <div style={{ color:"rgba(255,255,255,0.82)", fontSize:16, fontWeight:600, marginBottom:36 }}>
                {isRTL ? (pct>=80?"ممتاز! ":pct>=50?"جيد، واصل!":"راجع الدرس") : (pct>=80?"Excellent ! ":pct>=50?"Bien joué !":"Relis le cours")}
              </div>
              <button onClick={() => { setQIdx(0); setSelected(null); setRevealed(false); setAllAns({}); setQuizDone(false); }}
                style={{ width:"100%", background:"#fff", border:"none", borderRadius:18, padding:"18px", cursor:"pointer",
                  fontWeight:800, fontSize:16, color:tagColor, boxShadow:"0 6px 20px rgba(0,0,0,0.2)", marginBottom:14 }}>
                {isRTL ? " إعادة" : " Recommencer"}
              </button>
              <button onClick={() => setActiveTab("hub")}
                style={{ width:"100%", background:"rgba(255,255,255,0.15)", border:"2px solid rgba(255,255,255,0.4)",
                  borderRadius:18, padding:"16px", cursor:"pointer", fontWeight:700, fontSize:15, color:"#fff" }}>
                {isRTL ? "← القائمة" : "← Menu"}
              </button>
            </div>
          </div>
        );
      }

      return (
        <div style={{ fontFamily:"'Segoe UI',system-ui,sans-serif", minHeight:"100vh",
          background:tagColor, position:"relative", overflow:"hidden", direction:dir,
          width:"100%", margin:0, padding:0 }}>
          <GlobalStyles />
          {/* Large blob top-left */}
          <div style={{ position:"absolute", top:-120, left:-120, width:340, height:340, borderRadius:"50%",
            background:"rgba(255,255,255,0.13)", pointerEvents:"none" }}/>
          {/* Medium blob upper-right */}
          <div style={{ position:"absolute", top:-60, right:-80, width:230, height:230, borderRadius:"50%",
            background:"rgba(255,255,255,0.09)", pointerEvents:"none" }}/>
          {/* Medium blob mid-left */}
          <div style={{ position:"absolute", top:260, left:-100, width:240, height:240, borderRadius:"50%",
            background:"rgba(255,255,255,0.09)", pointerEvents:"none" }}/>

          {/*  Bottom organic leaf/plant wave  */}
          <svg style={{ position:"absolute", bottom:0, left:0, width:"100%", pointerEvents:"none", zIndex:0 }}
            viewBox="0 0 430 160" preserveAspectRatio="none">
            {/* Back layer - deeper dark */}
            <path d="M0,130 Q30,80 70,110 Q110,140 150,90 Q180,50 210,80 Q240,110 280,60 Q310,20 350,55 Q385,85 430,50 L430,160 L0,160 Z"
              fill="rgba(0,0,0,0.22)"/>
            {/* Front layer - organic leaf shapes */}
            <path d="M-10,155 Q10,120 40,140 Q60,155 80,125 Q100,95 130,118 Q155,138 175,108 Q195,78 225,100 Q255,122 280,95 Q305,68 335,88 Q360,105 385,80 Q405,60 440,75 L440,160 L-10,160 Z"
              fill="rgba(0,0,0,0.30)"/>
          </svg>

          {/*  Top bar: X button (left) + IA badge (right)  */}
          <div style={{ position:"relative", zIndex:2, display:"flex", alignItems:"center",
            justifyContent:"space-between", padding:"20px 20px 0" }}>
            <button onClick={() => setActiveTab("hub")} className="icon-btn"
              style={{ width:50, height:50, borderRadius:"50%", background:"rgba(60,0,100,0.45)",
                border:"none", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
                color:"#fff", fontSize:20, fontWeight:700, backdropFilter:"blur(4px)" }}>
              
            </button>
            <div style={{ background:"rgba(255,255,255,0.92)", borderRadius:14,
              padding:"8px 14px", display:"flex", alignItems:"center", gap:5,
              boxShadow:"0 2px 10px rgba(0,0,0,0.15)" }}>
              <span style={{ color:tagColor, fontSize:15, fontWeight:900 }}>IA</span>
              <span style={{ color:"#F5C518", fontSize:16 }}></span>
            </div>
          </div>

          {/*  Loading  */}
          {exercisesLoading && (
            <div style={{ position:"relative", zIndex:2, textAlign:"center",
              padding:"100px 20px", color:"rgba(255,255,255,0.9)", fontSize:16, fontWeight:700 }}>
              {isRTL ? "جارٍ التحميل…" : "Chargement…"}
            </div>
          )}

          {/*  Error  */}
          {exercisesError && !exercisesLoading && (
            <div style={{ position:"relative", zIndex:2, textAlign:"center", padding:"80px 24px" }}>
              <div style={{ fontSize:52, marginBottom:14 }}></div>
              <div style={{ color:"#fff", fontWeight:800, fontSize:17 }}>
                {isRTL ? "التمارين قادمة قريباً" : "Exercices bientôt disponibles"}
              </div>
            </div>
          )}

          {/*  Quiz question  */}
          {exercises && !exercisesLoading && currentQ && (
            <div style={{ position:"relative", zIndex:2, display:"flex", flexDirection:"column",
              alignItems:"center", paddingBottom:50 }}>

              {/* Subject circle + label */}
              <div style={{ display:"flex", flexDirection:"column", alignItems:"center", marginTop:24 }}>
                {/* White circle — matches screenshot size */}
                <div style={{ width:130, height:130, borderRadius:"50%", background:"#fff",
                  display:"flex", alignItems:"center", justifyContent:"center",
                  boxShadow:"0 8px 32px rgba(0,0,0,0.28)", position:"relative", zIndex:1 }}>
                  <div style={{ width:60, height:60, borderRadius:"50%", background: matiere?.color || PURPLE, opacity:0.85 }} />
                  {/* Yellow accent bar bottom-left */}
                  <div style={{ position:"absolute", bottom:16, left:8, width:30, height:10,
                    borderRadius:99, background:"#F5C518", transform:"rotate(-25deg)" }}/>
                </div>
                {/* Dark pill — overlaps circle bottom */}
                <div style={{ background:"rgba(30,10,60,0.55)", borderRadius:24,
                  padding:"8px 28px", marginTop:-18, zIndex:2,
                  boxShadow:"0 2px 12px rgba(0,0,0,0.30)" }}>
                  <span style={{ color:"#fff", fontSize:15, fontWeight:800, letterSpacing:0.2 }}>
                    {matiere?.name || matiere?.label || ""}
                  </span>
                </div>
              </div>

              {/* Question text */}
              <div style={{ padding:"28px 28px 22px", textAlign:"center", width:"100%", boxSizing:"border-box" }}>
                <div style={{ color:"#fff", fontSize:22, fontWeight:900, lineHeight:1.5 }}>
                  {currentQ.question}
                </div>
              </div>

              {/*  QCM options  */}
              {currentQ.type === "qcm" && currentQ.options && (
                <div style={{ width:"100%", padding:"0 18px", display:"flex", flexDirection:"column",
                  gap:16, boxSizing:"border-box" }}>
                  {currentQ.options.map((opt, j) => {
                    const isSel   = selected === opt;
                    const isOptOk = revealed && opt.trim().toLowerCase() === correct;
                    const isOptBad= revealed && isSel && !isOptOk;
                    return (
                      <button key={j} className="option-btn"
                        onClick={() => !revealed && setSelected(opt)}
                        style={{
                          width:"100%",
                          background: isOptOk ? "#E8F5E9" : isOptBad ? "#FFEBEE" : "#fff",
                          border: isSel && !revealed ? "3px solid rgba(255,255,255,0.8)"
                            : isOptOk ? "3px solid #4CAF50"
                            : isOptBad ? "3px solid #F44336"
                            : "3px solid transparent",
                          borderRadius:20,
                          padding:"20px 22px",
                          cursor: revealed ? "default" : "pointer",
                          textAlign: isRTL ? "right" : "left",
                          fontSize:16, fontWeight: isSel ? 600 : 400,
                          color: isOptOk ? "#1B5E20" : isOptBad ? "#B71C1C" : "#2a2a2a",
                          /* Thick dark-purple bottom shadow from screenshot */
                          boxShadow: isOptOk
                            ? "0 6px 0 #388E3C, 0 10px 20px rgba(0,0,0,0.12)"
                            : isOptBad
                            ? "0 6px 0 #D32F2F, 0 10px 20px rgba(0,0,0,0.12)"
                            : isSel && !revealed
                            ? "0 6px 0 rgba(80,0,140,0.55), 0 10px 20px rgba(0,0,0,0.18)"
                            : "0 6px 0 rgba(80,0,140,0.35), 0 10px 20px rgba(0,0,0,0.12)",
                          display:"flex", alignItems:"center",
                          justifyContent:"space-between", direction:dir, boxSizing:"border-box",
                          transition:"all 0.15s ease"
                        }}>
                        <span>{opt}</span>
                        {isOptOk  && <span style={{ fontSize:20 }}></span>}
                        {isOptBad && <span style={{ fontSize:20 }}></span>}
                      </button>
                    );
                  })}
                </div>
              )}

              {/*  Vrai / Faux  */}
              {currentQ.type === "vrai_faux" && (
                <div style={{ width:"100%", padding:"0 18px", display:"flex", flexDirection:"column",
                  gap:14, boxSizing:"border-box" }}>
                  {(isRTL ? ["صح","خطأ"] : ["Vrai","Faux"]).map((label, j) => {
                    const val = ["صح","خطأ"][j];
                    const isSel    = selected === val;
                    const isOptOk  = revealed && val.trim() === currentQ.answer.trim();
                    const isOptBad = revealed && isSel && !isOptOk;
                    return (
                      <button key={label} className="option-btn"
                        onClick={() => !revealed && setSelected(val)}
                        style={{
                          width:"100%", background: isOptOk ? "#E8F5E9" : isOptBad ? "#FFEBEE" : "#fff",
                          border: isSel && !revealed ? "3px solid rgba(255,255,255,0.8)"
                            : isOptOk ? "3px solid #4CAF50" : isOptBad ? "3px solid #F44336" : "3px solid transparent",
                          borderRadius:20, padding:"20px 22px", cursor: revealed ? "default" : "pointer",
                          fontSize:16, fontWeight: isSel ? 700 : 400,
                          color: isOptOk ? "#1B5E20" : isOptBad ? "#B71C1C" : "#2a2a2a",
                          boxShadow: isOptOk
                            ? "0 6px 0 #388E3C, 0 10px 20px rgba(0,0,0,0.12)"
                            : isOptBad
                            ? "0 6px 0 #D32F2F, 0 10px 20px rgba(0,0,0,0.12)"
                            : "0 6px 0 rgba(80,0,140,0.35), 0 10px 20px rgba(0,0,0,0.12)",
                          display:"flex", alignItems:"center", justifyContent:"space-between",
                          transition:"all 0.15s ease"
                        }}>
                        <span>{j===0?" ":" "}{label}</span>
                        {isOptOk  && <span style={{ fontSize:20 }}></span>}
                        {isOptBad && <span style={{ fontSize:20 }}></span>}
                      </button>
                    );
                  })}
                </div>
              )}

              {/*  Open text  */}
              {(currentQ.type === "completion" || currentQ.type === "question_ouverte") && (
                <div style={{ width:"100%", padding:"0 18px", boxSizing:"border-box" }}>
                  <textarea value={selected || ""} onChange={e => !revealed && setSelected(e.target.value)}
                    placeholder={isRTL ? "اكتب إجابتك هنا…" : "Écris ta réponse ici…"}
                    rows={currentQ.type === "question_ouverte" ? 4 : 2}
                    style={{ width:"100%", borderRadius:16,
                      border: revealed ? (selIsOk ? "3px solid #4CAF50" : selIsBad ? "3px solid #F44336" : "3px solid rgba(255,255,255,0.4)") : "3px solid rgba(255,255,255,0.4)",
                      padding:"16px 18px", fontSize:15, fontFamily:"inherit", resize:"none",
                      color:"#2D2D3A", outline:"none", background:"#fff",
                      boxSizing:"border-box", direction:dir, textAlign:isRTL?"right":"left",
                      boxShadow:"0 5px 0 rgba(0,0,0,0.22)" }} />
                </div>
              )}

              {/* Correct answer hint */}
              {revealed && selIsBad && (
                <div style={{ width:"100%", padding:"12px 18px 0", boxSizing:"border-box" }}>
                  <div style={{ background:"rgba(0,0,0,0.20)", borderRadius:14, padding:"12px 16px",
                    direction:dir, textAlign:isRTL?"right":"left" }}>
                    <span style={{ fontSize:14, fontWeight:800, color:"#FFD700" }}>
                      {isRTL ? " الجواب الصحيح: " : " Bonne réponse : "}
                    </span>
                    <span style={{ fontSize:14, color:"#fff", fontWeight:600 }}>{currentQ.answer}</span>
                  </div>
                </div>
              )}

              {/*  Verify / Next button  */}
              <div style={{ width:"100%", padding:"26px 18px 16px", boxSizing:"border-box" }}>
                {!revealed ? (
                  <button
                    onClick={() => {
                      if (!selected) return;
                      setRevealed(true);
                      setAllAns(a => ({ ...a, [qIdx]: selected }));
                    }}
                    style={{
                      width:"100%",
                      background: selected ? "#fff" : "rgba(255,255,255,0.25)",
                      border:"none", borderRadius:18, padding:"18px",
                      cursor: selected ? "pointer" : "not-allowed",
                      fontWeight:800, fontSize:17,
                      color: selected ? tagColor : "rgba(255,255,255,0.5)",
                      boxShadow: selected ? "0 5px 0 rgba(0,0,0,0.22), 0 8px 20px rgba(0,0,0,0.15)" : "none",
                      transition:"all 0.2s"
                    }}>
                    {isRTL ? " تحقق من الإجابة" : " Vérifier"}
                  </button>
                ) : (
                  <button
                    onClick={() => {
                      if (qIdx + 1 < totalQ) {
                        setQIdx(i => i + 1);
                        setSelected(null);
                        setRevealed(false);
                      } else {
                        const pct = Math.round((finalScore / totalQ) * 100);
                        onQuizDone(pct);
                        setQuizDone(true);
                      }
                    }}
                    style={{
                      width:"100%", background:"#fff", border:"none", borderRadius:18, padding:"18px",
                      cursor:"pointer", fontWeight:800, fontSize:17, color:tagColor,
                      boxShadow:"0 5px 0 rgba(0,0,0,0.22), 0 8px 20px rgba(0,0,0,0.15)"
                    }}>
                    {qIdx + 1 < totalQ
                      ? (isRTL ? "← التالي" : "Suivant →")
                      : (isRTL ? " النتائج" : " Résultats")}
                  </button>
                )}
              </div>

              {/* Counter */}
              <div style={{ marginTop:16, marginBottom:40, color:"rgba(255,255,255,0.65)", fontSize:13, fontWeight:600 }}>
                {qIdx + 1} / {totalQ}
              </div>
            </div>
          )}
        </div>
      );
    }

    //  Hub page (default / activeTab === "hub") 
    return (
      <div style={{ fontFamily: "'Segoe UI', system-ui, sans-serif", background: hubBg, minHeight: "100vh", maxWidth: "100%", margin: "0 auto", direction: (isRTL) ? "rtl" : "ltr" }}>
        <GlobalStyles />
        {/* Back button + progress ring area */}
        <div style={{ position: "relative", paddingTop: 56, paddingBottom: 0, textAlign: "center" }}>
          <button onClick={() => { setPage(5); setExercises(null); setExercisesError(null); setLessonContent(null); setLessonError(null); setActiveTab("hub"); }}
            className="icon-btn"
            style={{ position: "absolute", top: 14, left: 16, background: "#fff", border: "none", borderRadius: 50, width: 40, height: 40,
              cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: 20, color: DARK, boxShadow: "0 2px 10px rgba(0,0,0,0.12)" }}><img src={BACK_ICON_SRC} alt="back" style={{ width: 18, height: 18 }} /></button>

          {/* Progress ring (decorative) */}
          <div style={{ width: 64, height: 64, borderRadius: "50%", background: "#E8DECE", border: "3px dashed #ccc",
            display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 16px",
            boxShadow: "0 2px 8px rgba(0,0,0,0.08)" }}>
            <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#aaa" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="20 6 9 17 4 12"/>
            </svg>
          </div>

          {/* Lesson title */}
          <div style={{ padding: "0 24px 24px", fontSize: 20, fontWeight: 800, color: DARK, lineHeight: 1.3 }}>{text}</div>
        </div>

        {/* Card grid */}
        <div style={{ padding: "0 16px 120px", display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
          {HUB_CARDS.map(({ key, label, Icon, color, bg, available, badge, done }) => (
            <button key={key} className="card-btn"
              onClick={() => {
                if (!available) return;
                if (key === "cours") { loadLesson(lesson); setActiveTab("cours"); }
                if (key === "exercices") { loadExercises(lesson); setActiveTab("exercices"); }
              }}
              style={{ background: "#fff", border: "none", borderRadius: 20, padding: "22px 16px 18px",
                cursor: available ? "pointer" : "default", textAlign: "center",
                boxShadow: "0 2px 16px rgba(0,0,0,0.07)", opacity: available || badge ? 1 : 0.85,
                display: "flex", flexDirection: "column", alignItems: "center", gap: 0, position: "relative" }}>

              {/* Icon bubble */}
              <div style={{ width: 72, height: 72, borderRadius: 18, background: bg,
                display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 10, position: "relative" }}>
                <Icon color={color} />
                {badge ? (
                  <div style={{ position: "absolute", bottom: -10, left: "50%", transform: "translateX(-50%)",
                    background: "#fff", borderRadius: 20, padding: "2px 10px", fontSize: 11, fontWeight: 800,
                    color: "#aaa", boxShadow: "0 1px 6px rgba(0,0,0,0.1)", whiteSpace: "nowrap" }}>
                    {badge}
                  </div>
                ) : (
                  /* Check badge */
                  <div style={{ position: "absolute", bottom: -8, left: "50%", transform: "translateX(-50%)",
                    width: 22, height: 22, borderRadius: "50%",
                    background: done ? color : "#fff",
                    border: `2px solid ${done ? color : (available ? color : "#ddd")}`,
                    display: "flex", alignItems: "center", justifyContent: "center",
                    pointerEvents: "none" }}>
                    <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke={done ? "#fff" : (available ? color : "#ccc")} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                      <polyline points="20 6 9 17 4 12"/>
                    </svg>
                  </div>
                )}
              </div>

              <div style={{ marginTop: badge ? 14 : 10, fontSize: 15, fontWeight: 700, color: DARK }}>{label}</div>
            </button>
          ))}
        </div>

        <BottomNav active="matieres" />
      </div>
    );
  }

  return null;
}

